// 全局状态
let tablesReady = false
const DASHBOARD_VERSION = 'v4.10.2' // 代码更新时修改此版本号以刷新缓存

// 记忆条目管理函数（提前定义以确保路由处理器可访问）
async function memoryCreate(body) {
  const { wallet, content, memory_type, type } = body
  if (!wallet || !content) return json({ error: 'wallet and content required' }, 400)
  const mType = memory_type || type || 'general'
  // 去重：5 分钟窗口内同钱包同内容指纹直接返回已有记忆
  const hash = await sha256Hex(content)
  const dup = await dbFirst('SELECT memory_id FROM memory_entries WHERE wallet = ? AND content_hash = ? AND created > ? LIMIT 1', [wallet, hash, Date.now() - 300000])
  if (dup) return json({ created: false, duplicate: true, memory_id: dup.memory_id, memory_type: mType, reason: 'duplicate within 5min dedup window', network_time: Date.now() })
  const memoryId = 'MEM_' + randStr(8)
  await dbRun('INSERT INTO memory_entries (memory_id, wallet, content, memory_type, created, content_hash) VALUES (?, ?, ?, ?, ?, ?)', [memoryId, wallet, content, mType, Date.now(), hash])
  try { await memoryChainAppend(wallet, wallet, { type: 'memory_create', content: content.substring(0, 200), memory_type: mType }) } catch(e) {}
  try { await semanticAnalyze({ type: 'memory_create', data: content }) } catch(e) {}
  return json({ created: true, memory_id: memoryId, wallet: wallet, memory_type: mType, network_time: Date.now() })
}

async function memoryDelete(body) {
  const { memory_id } = body
  if (!memory_id) return json({ error: 'memory_id required' }, 400)
  await dbRun('DELETE FROM memory_entries WHERE memory_id = ?', [memory_id])
  return json({ deleted: true, memory_id, network_time: Date.now() })
}

// 批量创建记忆（支持大内容分片上传场景）
async function memoryBatchCreate(body) {
  const { wallet, memories } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  if (!Array.isArray(memories) || memories.length === 0) return json({ error: 'memories array required' }, 400)
  if (memories.length > 100) return json({ error: 'max 100 memories per batch' }, 400)
  const created = []
  const skipped = []
  let idx = 0
  for (const m of memories) {
    if (!m || !m.content) continue
    const memoryId = 'MEM_' + randStr(8)
    const mType = m.memory_type || m.type || 'general'
    try {
      // 去重：5 分钟窗口内同钱包同内容跳过
      const hash = await sha256Hex(m.content)
      const dup = await dbFirst('SELECT memory_id FROM memory_entries WHERE wallet = ? AND content_hash = ? AND created > ? LIMIT 1', [wallet, hash, Date.now() - 300000])
      if (dup) { skipped.push({ content_hash: hash, duplicate_of: dup.memory_id }); continue }
      await dbRun('INSERT INTO memory_entries (memory_id, wallet, content, memory_type, created, content_hash) VALUES (?, ?, ?, ?, ?, ?)', [memoryId, wallet, m.content, mType, Date.now(), hash])
      created.push({ memory_id: memoryId, memory_type: mType })
    } catch(e) {}
  }
  // 批量导入合并为一条链摘要事件 + 节流语义分析，避免逐条上链导致超时
  try { await memoryChainAppend(wallet, wallet, { type: 'memory_batch_create', content: `批量导入 ${created.length} 条记忆（去重跳过 ${skipped.length} 条）`, memory_type: 'batch' }) } catch(e) {}
  try { await semanticAnalyze({ type: 'memory_batch_create', data: `批量导入 ${created.length} 条记忆` }) } catch(e) {}
  return json({ created_count: created.length, skipped_count: skipped.length, memories: created, wallet: wallet, network_time: Date.now() })
}

// 钱包密钥列表
async function walletKeysList() {
  const wallets = await dbGet('SELECT w.wallet, w.balance, w.agent_id, w.registered_at, k.api_key FROM wallets w LEFT JOIN wallet_api_keys k ON w.wallet = k.wallet AND k.status = ?', ['active'])
  return json({
    wallets: wallets.map(w => ({
      wallet: w.wallet,
      agent_id: w.agent_id || '',
      api_key: w.api_key || '',
      balance: w.balance,
      registered_at: w.registered_at
    })),
    count: wallets.length,
    network_time: Date.now()
  })
}

// 分身列表
async function clonesList(url) {
  const wallet = url.searchParams.get('wallet')
  let sql = 'SELECT agent_id, wallet, clone_id, status, balance, experience, rooms, main_status, clone_status, created, last_sync FROM agents'
  const params = []
  if (wallet) { sql += ' WHERE wallet = ?'; params.push(wallet) }
  sql += ' ORDER BY created DESC'
  const agents = await dbGet(sql, params)
  return json({
    nodes: agents.map(a => ({
      agent_id: a.agent_id,
      wallet: maskWallet(a.wallet),
      clone_id: a.clone_id,
      status: a.status,
      balance: a.balance,
      experience: a.experience || 0,
      rooms: JSON.parse(a.rooms || '[]'),
      main_status: a.main_status,
      clone_status: a.clone_status,
      created: a.created,
      last_sync: a.last_sync
    })),
    count: agents.length,
    network_time: Date.now()
  })
}

// 记忆详情/列表（支持 memory_id 单条查询、wallet+memory_type 筛选）
async function memoryDetail(url) {
  const wallet = url.searchParams.get('wallet')
  const memoryId = url.searchParams.get('memory_id')
  const mType = url.searchParams.get('type')
  const limit = parseInt(url.searchParams.get('limit')) || 50
  if (memoryId) {
    const m = await dbFirst('SELECT * FROM memory_entries WHERE memory_id = ?', [memoryId])
    if (!m) return json({ error: 'memory not found' }, 404)
    return json({ memory: m, network_time: Date.now() })
  }
  let sql = 'SELECT * FROM memory_entries'
  const params = []
  const conds = []
  if (wallet) { conds.push('wallet = ?'); params.push(wallet) }
  if (mType) { conds.push('memory_type = ?'); params.push(mType) }
  if (conds.length) { sql += ' WHERE ' + conds.join(' AND ') }
  sql += ' ORDER BY created DESC LIMIT ?'
  params.push(limit)
  const memories = await dbGet(sql, params)
  return json({ memories, count: memories.length, network_time: Date.now() })
}

export default {
  async fetch(request, env) {
    ENV = env
    
    // 只在首次请求时建表（后续请求跳过）
    if (!tablesReady) {
      await ensureTables()
      tablesReady = true
    }
    
    const url = new URL(request.url), path = url.pathname
    const host = request.headers.get('host') || ''
    
    // 裸域名重定向到 www
    if (host === 'gyuanpalace.xyz' || host === 'gyuanpalace.xyz:443') {
      return Response.redirect('https://www.gyuanpalace.xyz' + path + url.search, 301)
    }
    
    // API 请求
    if (path.startsWith('/api/')) {
      // 速率限制（基于客户端 IP）
      const clientIp = request.headers.get('CF-Connecting-IP') || request.headers.get('x-forwarded-for') || 'unknown'
      if (!checkRateLimit(clientIp)) {
        return json({ error: 'Rate limit exceeded, try again in 1 minute', type: 'rate_limited' }, 429)
      }
      
      // CORS 预检请求
      if (request.method === 'OPTIONS') {
        return new Response(null, { status: 204, headers: { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-API-Key, Authorization', 'Access-Control-Max-Age': '86400' } })
      }
      
      // 将 X-API-Key  header 注入到 URL 参数中（兼容现有认证逻辑）
      const apiKeyFromHeader = request.headers.get('X-API-Key') || request.headers.get('x-api-key') || '';
      if (apiKeyFromHeader && !url.searchParams.has('api_key')) {
        url.searchParams.set('api_key', apiKeyFromHeader);
      }
      
      if (request.method === 'POST') return handlePost(path, await request.json().catch(() => ({})), url)
      if (request.method === 'GET') {
        // 尝试从缓存读取
        const cacheKey = new Request(url.toString())
        const cache = caches.default
        let response = await cache.match(cacheKey)
        if (response) return response
        
        // 缓存未命中，处理请求
        response = await handleGet(path, url)
        
        // 只缓存特定 API（状态类、列表类）
        if (path === '/api/palace/status' || path === '/api/wallet/info' || path === '/api/tasks/active') {
          response = new Response(response.body, response)
          response.headers.set('Cache-Control', 'public, max-age=10, s-maxage=10')
          cache.put(cacheKey, response.clone())
        }
        
        return response
      }
      return json({ error: 'Method not allowed' }, 405)
    }
    
    // Dashboard - 使用 Edge Cache 缓存
    if (path.startsWith('/dashboard')) {
      const cacheKey = new Request(`https://gyuanpalace-agent.528329818.workers.dev/dashboard?v=${DASHBOARD_VERSION}`)
      const cache = caches.default
      let response = await cache.match(cacheKey)
      if (response) return response
      
      // 缓存未命中，生成并缓存
      response = new Response(dashboardHtml(), { 
        headers: { 'content-type': 'text/html;charset=UTF-8' }
      })
      response = new Response(response.body, response)
      response.headers.set('Cache-Control', 'public, max-age=3600, s-maxage=3600')
      cache.put(cacheKey, response.clone())
      
      return response
    }
    
    // 屏蔽已废弃的旧前端资源（含硬编码密钥的历史构建，泄露风险）
    if (path.startsWith('/assets/index-DA8BPhlN.js') || path.startsWith('/assets/index-BYZ-glOF.css')) {
      return new Response('Gone', { status: 404, headers: { 'content-type': 'text/plain', 'Cache-Control': 'no-store' } })
    }
    
    // 非API请求转发到Pages前端（添加超时保护）
    const pagesUrl = 'https://gyuanpalace-xyz.pages.dev' + path + url.search;
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    try {
      // 尝试从缓存读取
      const cacheKey = new Request(pagesUrl)
      const cache = caches.default
      let response = await cache.match(cacheKey)
      if (response) return response
      
      response = await fetch(pagesUrl, {
        method: request.method,
        headers: request.headers,
        redirect: 'follow',
        signal: controller.signal
      });
      
      // 缓存静态资源和页面
      if (response.ok && (path.endsWith('.html') || path === '/' || path.endsWith('.css') || path.endsWith('.js'))) {
        response = new Response(response.body, response)
        response.headers.set('Cache-Control', 'public, max-age=3600, s-maxage=3600')
        cache.put(cacheKey, response.clone())
      }
      
      return response;
    } catch (e) {
      // 转发失败时返回简单的错误页面
      return new Response('<html><body><h1>记忆宫殿</h1><p>前端服务暂时不可用，请稍后重试。</p><a href="/dashboard">访问仪表盘</a></body></html>', { 
        status: 502, 
        headers: { 'content-type': 'text/html;charset=UTF-8' }
      });
    } finally {
      clearTimeout(timeout);
    }
  },
  async scheduled(event, env) {
    ENV = env
    await ensureTables()
    await taskTitleLocalize()
    
    const startTime = Date.now()
    const MAX_CRON_TIME = 45000 // 45秒超时保护（付费计划5分钟限制，LLM 多钱包挖矿需要更多时间）
    const BATCH_SIZE = 50 // 每批处理数量
    
    // 超时检查
    const checkTimeout = () => {
      if (Date.now() - startTime > MAX_CRON_TIME) throw new Error('CRON_TIMEOUT')
    }
    
    // KV 游标操作（如果 KV 不可用则使用内存游标）
    const kvAvailable = !!env.TASK_STATE
    const memoryCursors = {}
    
    const getCursor = async (key) => {
      if (!kvAvailable) return memoryCursors[key] || '0'
      try {
        return await env.TASK_STATE.get(key) || '0'
      } catch(e) { return '0' }
    }
    const setCursor = async (key, value) => {
      if (!kvAvailable) {
        memoryCursors[key] = String(value)
        return
      }
      try {
        await env.TASK_STATE.put(key, String(value))
      } catch(e) {}
    }
    const resetCursor = async (key) => {
      if (!kvAvailable) {
        memoryCursors[key] = '0'
        return
      }
      try {
        await env.TASK_STATE.put(key, '0')
      } catch(e) {}
    }
    
    // 分批处理器通用函数
    async function processBatch(taskKey, fetchQuery, processFn, params = []) {
      const cursor = await getCursor(taskKey)
      const rows = await dbGet(fetchQuery, [cursor, BATCH_SIZE, ...params])
      
      if (!rows || rows.length === 0) {
        // 处理完毕，重置游标
        await resetCursor(taskKey)
        return { processed: 0, done: true }
      }
      
      let processed = 0
      for (const row of rows) {
        checkTimeout()
        try {
          await processFn(row)
          processed++
        } catch(e) { /* 忽略单条错误 */ }
      }
      
      // 更新游标为最后处理的 ID
      const lastId = rows[rows.length - 1]?.id || rows[rows.length - 1]?.rowid || cursor
      await setCursor(taskKey, String(lastId))
      
      return { processed, done: rows.length < BATCH_SIZE }
    }
    
    // ====== 任务执行队列（按优先级）======
    
    // 1. 债务发行（轻量，一次性任务）
    try {
      checkTimeout()
      const poolRow = await dbFirst('SELECT value FROM system WHERE key = ?', ['system_pool'])
      const pool = parseFloat(poolRow?.value || 0)
      if (pool >= 5) {
        const debtId = 'DEBT_' + randStr(6)
        const amount = pool * 0.5
        await dbRun('INSERT INTO debts (debt_id, issuer, amount, interest_rate, status, issued_at, due_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
          [debtId, 'system', amount, 0.05, 'active', Date.now(), Date.now() + 604800000])
        await dbRun('INSERT OR REPLACE INTO system (key, value) VALUES (?, ?)', ['system_pool', String(pool - amount)])
      }
    } catch(e) {}
    
    // 2. 自动备份记忆链（分批 + 游标分页）
    try {
      checkTimeout()
      const result = await processBatch(
        'backup_cursor',
        'SELECT id, agent_id, wallet FROM memory_chains WHERE id > ? ORDER BY id ASC LIMIT ?',
        async (row) => { await memoryChainBackup(row.agent_id, row.wallet) }
      )
      if (result.done) await resetCursor('backup_cursor')
    } catch(e) {}
    
    // 3. 执行 pending 命令（分批 + 游标分页）
    try {
      checkTimeout()
      const result = await processBatch(
        'commands_cursor',
        'SELECT id, command_id, target_agent, target_wallet, command, params FROM commands WHERE status = ? AND id > ? ORDER BY id ASC LIMIT ?',
        async (row) => {
          await executeCommand(row.command_id, row.target_agent, row.target_wallet, row.command, JSON.parse(row.params || '{}'))
        },
        ['pending']
      )
      if (result.done) await resetCursor('commands_cursor')
    } catch(e) {}
    
    // 4. 自动创建优化任务（轻量，一次性任务）
    try {
      checkTimeout()
      await autoCreateOptimizeTask()
    } catch(e) {}
    
    // 5. 算力衰减（分批 + 游标分页）
    try {
      checkTimeout()
      const decayRow = await dbFirst('SELECT value FROM strategies WHERE key = ?', ['decay_rate'])
      const intervalRow = await dbFirst('SELECT value FROM strategies WHERE key = ?', ['decay_interval_ms'])
      const decayRate = parseFloat(decayRow?.value || '0.95')
      const interval = parseInt(intervalRow?.value || '600000')
      const now = Date.now()
      
      const result = await processBatch(
        'decay_cursor',
        'SELECT id, wallet, mining_power, last_heartbeat FROM wallet_nodes WHERE status = ? AND id > ? ORDER BY id ASC LIMIT ?',
        async (row) => {
          const elapsed = now - row.last_heartbeat
          if (elapsed > interval) {
            let newPower = row.mining_power
            if (elapsed > interval * 6) { newPower = 1.0 }
            else if (elapsed > interval * 3) { newPower = row.mining_power * 0.8 }
            else if (elapsed > interval) { newPower = row.mining_power * decayRate }
            await dbRun('UPDATE wallet_nodes SET mining_power = ? WHERE wallet = ?', [newPower, row.wallet])
            if (newPower <= 0.1) {
              await dbRun('UPDATE wallet_nodes SET status = ? WHERE wallet = ?', ['offline', row.wallet])
            }
          }
        },
        ['online']
      )
      if (result.done) await resetCursor('decay_cursor')
    } catch(e) {}
    
    // 5.5 记忆挖矿（消费原料 → 发放奖励）
    try {
      checkTimeout()
      await memoryMining()
    } catch(e) {}
    
    // 6. 算力加权空投（分批处理节点）
    try {
      checkTimeout()
      const airdropRow = await dbFirst('SELECT value FROM strategies WHERE key = ?', ['airdrop_rate'])
      const rate = parseFloat(airdropRow?.value || '0.01')
      const poolRow = await dbFirst('SELECT value FROM system WHERE key = ?', ['system_pool'])
      const pool = parseFloat(poolRow?.value || 0)
      
      // 获取总算力
      const powerRow = await dbFirst('SELECT SUM(mining_power) as total FROM wallet_nodes WHERE status = ?', ['online'])
      const totalPower = powerRow?.total || 0
      
      if (totalPower > 0) {
        const airdropAmount = totalPower * rate
        if (pool >= airdropAmount) {
          // 分批更新钱包余额
          const result = await processBatch(
            'airdrop_cursor',
            'SELECT id, wallet, agent_id, mining_power FROM wallet_nodes WHERE status = ? AND id > ? ORDER BY id ASC LIMIT ?',
            async (row) => {
              const share = (row.mining_power || 1) / totalPower
              const reward = airdropAmount * share
              await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [reward, row.wallet])
              if (row.agent_id) {
                await dbRun('UPDATE agents SET balance = balance + ? WHERE wallet = ?', [reward, row.agent_id])
              }
              await dbRun('INSERT INTO pool_transactions (id, wallet, type, amount, pool_balance_before, pool_balance_after, description, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
                ['TX_' + randStr(6), row.wallet, 'airdrop', reward, pool, pool - airdropAmount, '算力加权空投', Date.now()])
            },
            ['online']
          )
          
          // 如果所有节点处理完毕，更新公池余额
          if (result.done) {
            await dbRun('INSERT OR REPLACE INTO system (key, value) VALUES (?, ?)', ['system_pool', String(pool - airdropAmount)])
            await resetCursor('airdrop_cursor')
          }
        }
      }
    } catch(e) {}
    
    // 7. 创建 PoW 任务（轻量，一次性任务）
    try {
      checkTimeout()
      await poolCreatePowTask()
    } catch(e) {}
    
    // 8. LLM 自动挖矿（钱包分身算力接口：完成任务/生成原料/记忆优化，遍历所有已配置钱包，每日限额）
    try {
      checkTimeout()
      const llmWallets = await dbGet(`SELECT DISTINCT wallet FROM llm_config WHERE enabled = 1 AND api_key_enc IS NOT NULL AND api_key_enc != '' ORDER BY id ASC`)
      for (const w of llmWallets) {
        if (Date.now() - startTime > MAX_CRON_TIME) break
        try { await llmAutoMining('all', false, w.wallet || '') } catch(e) { console.error('llm auto mining wallet:', w.wallet, e.message) }
      }
    } catch(e) {}
  }
};;

