async function taskDelete(body) {
  const { task_id } = body
  if (!task_id) return json({ error: 'task_id required' }, 400)
  const task = await dbFirst('SELECT * FROM tasks WHERE task_id = ?', [task_id])
  if (!task) return json({ error: 'Task not found' }, 404)
  await dbRun('DELETE FROM tasks WHERE task_id = ?', [task_id])
  return json({ deleted: true, task_id })
}

async function taskClearAll(body) {
  const { confirm } = body
  if (confirm !== true) return json({ error: 'Must pass confirm: true to clear all tasks' }, 400)
  await dbRun('DELETE FROM tasks')
  return json({ cleared: true, message: 'All tasks have been cleared', network_time: Date.now() })
}

// ============================================================
// 🔒 安全扫描系统
// ============================================================
async function toolsInitSecurity(body) {
  const { agent_id, target_url, scan_type } = body
  if (!target_url) return json({ error: 'target_url required' }, 400)
  const scanId = 'SCAN_' + randStr(6)
  const scanType = scan_type || 'vulnerability_scan'
  await dbRun('INSERT INTO security_scan_tasks (scan_id, agent_id, target_url, scan_type, status, findings, severity_summary, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
    [scanId, agent_id || '', target_url, scanType, 'running', '[]', '{}', Date.now()])
  const findings = []
  const severityCount = { critical: 0, high: 0, medium: 0, low: 0, info: 0 }
  let requests = 0
  const baseUrl = target_url.endsWith('/') ? target_url.slice(0, -1) : target_url
  const scanConfigs = {
    vulnerability_scan: [
      { path: '/', check: 'security_headers' },
      { path: '/.env', check: 'sensitive_file' },
      { path: '/.git/config', check: 'git_exposure' },
      { path: '/api/', check: 'api_exposure' },
      { path: '/admin', check: 'admin_panel' },
      { path: '/wp-admin', check: 'wordpress_admin' },
      { path: '/phpmyadmin', check: 'database_admin' },
      { path: '/debug', check: 'debug_endpoint' },
      { path: '/config.json', check: 'config_file' },
      { path: '/api_keys', check: 'api_keys_exposure' }
    ],
    penetration_test: [
      { path: '/', check: 'method_enumeration' },
      { path: '/api/', check: 'api_method_enumeration' },
      { path: '/login', check: 'login_page' },
      { path: '/register', check: 'registration_page' },
      { path: '/password-reset', check: 'password_reset' },
      { path: '/.htaccess', check: 'htaccess_exposure' },
      { path: '/web.config', check: 'web_config_exposure' },
      { path: '/server-status', check: 'server_status' },
      { path: '/actuator', check: 'spring_actuator' },
      { path: '/env', check: 'env_exposure' }
    ],
    port_scan: [
      { path: ':80', check: 'http_port' },
      { path: ':443', check: 'https_port' },
      { path: ':8080', check: 'http_alt' },
      { path: ':8443', check: 'https_alt' },
      { path: ':3000', check: 'node_port' },
      { path: ':5000', check: 'flask_port' },
      { path: ':8000', check: 'django_port' },
      { path: ':9000', check: 'custom_port' }
    ]
  }
  const checks = scanConfigs[scanType] || scanConfigs.vulnerability_scan
  for (const check of checks) {
    try {
      const url = baseUrl + check.path
      const start = Date.now()
      const resp = await fetch(url, { method: 'HEAD', redirect: 'manual' })
      requests++
      const duration = Date.now() - start
      if (resp.status < 400 && check.check === 'sensitive_file') {
        const finding = { check: check.check, url, status: resp.status, severity: 'critical', title: `敏感文件暴露: ${check.path}`, description: `Found accessible sensitive file at ${url}`, response_time_ms: duration }
        findings.push(finding)
        severityCount.critical++
      } else if (resp.status === 200 && ['admin_panel', 'database_admin', 'debug_endpoint', 'server_status'].includes(check.check)) {
        const finding = { check: check.check, url, status: resp.status, severity: 'high', title: `管理面板暴露: ${check.path}`, description: `Admin/debug panel accessible at ${url}`, response_time_ms: duration }
        findings.push(finding)
        severityCount.high++
      } else if (resp.status < 400) {
        const finding = { check: check.check, url, status: resp.status, severity: 'low', title: `Accessible: ${check.path}`, description: `Resource is accessible`, response_time_ms: duration }
        findings.push(finding)
        severityCount.low++
      }
    } catch(e) {}
  }
  if (scanType === 'vulnerability_scan') {
    try {
      const resp = await fetch(baseUrl, { method: 'GET' })
      requests++
      const headers = resp.headers
      if (!headers.get('content-security-policy')) {
        findings.push({ check: 'missing_csp', severity: 'medium', title: '缺少 Content-Security-Policy', description: '响应头中未设置 CSP' })
        severityCount.medium++
      }
      if (!headers.get('strict-transport-security')) {
        findings.push({ check: 'missing_hsts', severity: 'medium', title: '缺少 Strict-Transport-Security', description: '响应头中未设置 HSTS' })
        severityCount.medium++
      }
      if (!headers.get('x-content-type-options')) {
        findings.push({ check: 'missing_xcto', severity: 'low', title: '缺少 X-Content-Type-Options', description: '响应头中未设置 X-Content-Type-Options' })
        severityCount.low++
      }
      if (!headers.get('x-frame-options')) {
        findings.push({ check: 'missing_xfo', severity: 'medium', title: '缺少 X-Frame-Options', description: '响应头中未设置 X-Frame-Options，可能存在点击劫持风险' })
        severityCount.medium++
      }
    } catch(e) {}
  }
  await dbRun('UPDATE security_scan_tasks SET status = ?, findings = ?, severity_summary = ?, requests_count = ?, completed = ? WHERE scan_id = ?',
    ['completed', JSON.stringify(findings), JSON.stringify(severityCount), requests, Date.now(), scanId])
  return json({
    scan_id: scanId, scan_type: scanType, target_url, status: 'completed',
    total_findings: findings.length, severity_summary: severityCount,
    findings, requests_count: requests, completed: Date.now()
  })
}

async function palaceTrades(url) {
  const wallet = url.searchParams.get('wallet') || ''
  const limit = parseInt(url.searchParams.get('limit')) || 20
  const offset = parseInt(url.searchParams.get('offset')) || 0
  if (!wallet) return json({ error: 'wallet required' }, 400)
  const trades = await dbGet('SELECT * FROM memory_trades WHERE seller_wallet = ? OR buyer_wallet = ? ORDER BY created DESC LIMIT ? OFFSET ?',
    [wallet, wallet, limit, offset])
  return json({
    wallet: maskWallet(wallet),
    total: trades.length,
    trades: trades.map(t => ({
      trade_id: t.trade_id,
      from_wallet: maskWallet(t.seller_wallet),
      to_wallet: maskWallet(t.buyer_wallet),
      price: t.price,
      status: 'completed',
      memory_count: JSON.parse(t.memory_ids || '[]').length,
      created: t.created,
      completed: t.created
    }))
  })
}

// ============================================================
// 📦 Durable Objects (required by existing Worker config)
// ============================================================
export class PalaceClone {
  constructor(state, env) { this.state = state; this.env = env }
  async fetch(request) {
    const url = new URL(request.url)
    if (url.pathname === '/status') {
      const stored = await this.state.storage.get('clone_data')
      return Response.json({ status: 'active', data: stored || {} })
    }
    if (request.method === 'POST') {
      const data = await request.json().catch(() => ({}))
      await this.state.storage.put('clone_data', data)
      return Response.json({ stored: true })
    }
    if (url.pathname === '/heartbeat') {
      await this.state.storage.put('last_heartbeat', Date.now())
      return Response.json({ alive: true, timestamp: Date.now() })
    }
    return new Response('PalaceClone DO', { status: 200 })
  }
  async alarm() {
    await this.state.storage.put('last_alarm', Date.now())
  }
}

export class TaskScheduler {
  constructor(state, env) { this.state = state; this.env = env }
  async fetch(request) {
    const url = new URL(request.url)
    if (url.pathname === '/tasks') {
      const tasks = await this.state.storage.get('tasks') || []
      return Response.json({ tasks })
    }
    if (request.method === 'POST') {
      const data = await request.json().catch(() => ({}))
      const tasks = await this.state.storage.get('tasks') || []
      tasks.push({ ...data, created: Date.now() })
      await this.state.storage.put('tasks', tasks)
      return Response.json({ scheduled: true, task_count: tasks.length })
    }
    if (url.pathname === '/clear') {
      await this.state.storage.delete('tasks')
      return Response.json({ cleared: true })
    }
    return new Response('TaskScheduler DO', { status: 200 })
  }
  async alarm() {
    const tasks = await this.state.storage.get('tasks') || []
    const now = Date.now()
    const due = tasks.filter(t => (t.scheduled_at || 0) <= now)
    if (due.length > 0) {
      const remaining = tasks.filter(t => (t.scheduled_at || 0) > now)
      await this.state.storage.put('tasks', remaining)
    }
  }
}

const PROTOCOL = 'MemoryChain/1.0', VERSION = '4.10.1'
let ENV = null

// ============================================================
// 工具函数
// ============================================================
// 速率限制状态（内存级，按隔离实例统计）
const RATE_LIMIT_MAX = 120 // 每分钟最多 120 次请求
const RATE_LIMIT_WINDOW_MS = 60000
const rateLimits = new Map()
let currentRateRemaining = RATE_LIMIT_MAX

function checkRateLimit(ip) {
  const now = Date.now()
  let entry = rateLimits.get(ip)
  if (!entry || now - entry.windowStart > RATE_LIMIT_WINDOW_MS) {
    entry = { count: 0, windowStart: now }
    rateLimits.set(ip, entry)
  }
  entry.count++
  currentRateRemaining = Math.max(0, RATE_LIMIT_MAX - entry.count)
  return entry.count <= RATE_LIMIT_MAX
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json;charset=UTF-8', 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'GET, POST, OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type, X-API-Key, Authorization', 'X-RateLimit-Limit': String(RATE_LIMIT_MAX), 'X-RateLimit-Remaining': String(currentRateRemaining) } })
}
function randStr(len) {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789'
  let s = ''
  for (let i = 0; i < len; i++) s += chars[Math.floor(Math.random() * chars.length)]
  return s
}
function maskWallet(wallet) {
  if (!wallet || wallet.length < 10) return wallet
  return wallet.substring(0, 4) + '...' + wallet.substring(wallet.length - 4)
}
// 内容 SHA-256 指纹（用于记忆去重）
async function sha256Hex(s) {
  const enc = new TextEncoder()
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(s || ''))
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('')
}
async function hmacSign(message, key) {
  const enc = new TextEncoder()
  const cryptoKey = await crypto.subtle.importKey('raw', enc.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
  const sig = await crypto.subtle.sign('HMAC', cryptoKey, enc.encode(message))
  return Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('')
}
async function hmacVerify(message, signature, key) {
  const expected = await hmacSign(message, key)
  return expected === signature
}

// ============================================================
// D1 数据库封装
// ============================================================
function db() { return ENV.gyuanpalace_db }
async function dbGet(sql, params = []) { const r = db().prepare(sql); return (params.length ? await r.bind(...params).all() : await r.all())?.results || [] }
async function dbRun(sql, params = []) { const r = db().prepare(sql); return params.length ? await r.bind(...params).run() : await r.run() }
async function dbFirst(sql, params = []) { const r = await dbGet(sql, params); return r[0] || null }
async function dbBatch(statements) { return await db().batch(statements.map(s => db().prepare(s[0]).bind(...(s[1] || [])))) }

