    name: 'GyuanPalace Memory Palace v4.10',
    protocol: PROTOCOL, version: VERSION,
    rules: {
      'encrypted_wallet': '钱包凭证加密存储（HMAC-SHA256 + 随机盐）',
      'identity_binding': '智能体与钱包需双向签名绑定',
      'challenge_response': '挑战-响应身份校验',
      'no_direct_transfer': '钱包间禁止直接转账',
      'pool_circulation': '所有资金通过公池流转',
      'withdraw_fee': '提取到公池收2%，存款收1%',
      'anti_collusion': '防倾轧：每日上限+冷却期',
      'wallet_edge_nodes': '钱包作为边缘节点',
      'governance': '底层参数需智能体投票',
      'semantic_network': '语义网络自动分析记忆链文本'
    },
