// ============================================================
async function toolCallLog(body) {
  const { wallet, agent_id, tool_name, input, output, duration_ms, success, context_id } = body
  if (!wallet || !tool_name) return json({ error: 'wallet and tool_name required' }, 400)
  
  // 认证 + 归属校验
  const authCtx = {}
  const url = new URL('http://localhost/api/tools/call/log')
  url.searchParams.set('wallet', wallet)
  for (const [k, v] of Object.entries(body)) {
    if (k.startsWith('session_token') || k.startsWith('api_key')) {
      url.searchParams.set(k, v)
    }
  }
  const auth = await verifySession(url)
  if (!auth.auth) {
    const status = auth.error === 'cross-wallet access forbidden' ? 403 : 401
    return json({ error: auth.error || 'authentication required (session_token or api_key)' }, status)
  }
  
  const logId = 'TL_' + randStr(8)
  const isSuccess = success !== false
  await dbRun('INSERT INTO tool_call_log (id, wallet, agent_id, tool_name, tool_params, result_status, result_data, duration_ms, context_before, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [logId, wallet, agent_id || '', tool_name, JSON.stringify(input || {}), isSuccess ? 'success' : 'error', JSON.stringify(output || {}), duration_ms || 0, context_id || '', Date.now(), 0])
  try { await memoryChainAppend(agent_id || wallet, wallet, { type: 'tool_call', tool_name, success: isSuccess }) } catch(e) {}
  return json({ logged: true, log_id: logId, network_time: Date.now() })
}

async function toolCallStatsGet(url) {
  const wallet = url.searchParams.get('wallet')
  let sql = 'SELECT tool_name, COUNT(*) as call_count, SUM(CASE WHEN result_status = ? THEN 1 ELSE 0 END) as success_count, AVG(duration_ms) as avg_duration FROM tool_call_log'
  const params = ['success']
  if (wallet) { sql += ' WHERE wallet = ?'; params.push(wallet) }
  sql += ' GROUP BY tool_name ORDER BY call_count DESC LIMIT 50'
  const stats = await dbGet(sql, params)
  return json({ stats, network_time: Date.now() })
}

