// ⛏️ 记忆挖矿管线：消费原料 → 知识提炼 → 按质结算
// ============================================================

// 质量评分算法：根据内容 richness 计算 0-100 分
function computeQualityScore(content, sourceType) {
  if (!content) return 0
  let score = 10 // 基础分
  const len = content.length
  score += Math.min(20, Math.floor(len / 50)) * 1.5 // 长度加分，上限 30
  if (sourceType === 'tool_call') score += 10
  else if (sourceType === 'dialog') score += 15
  else if (sourceType === 'manual') score += 20
  const hasInput = /input|输入|参数|param/i.test(content)
  const hasOutput = /output|输出|结果|result|返回/i.test(content)
  if (hasInput && hasOutput) score += 15 // 有输入有输出 = 完整知识
  return Math.min(100, Math.round(score))
}

// 根据质量分决定奖励
function rewardForQuality(score) {
  if (score >= 80) return { mc: 0.04, exp: 20, tier: 'S' }
  if (score >= 50) return { mc: 0.02, exp: 10, tier: 'A' }
  if (score >= 20) return { mc: 0.01, exp: 5, tier: 'B' }
  return { mc: 0.005, exp: 2, tier: 'C' }
}

// 内容归一化哈希（用于去重）
function normalizeHash(s) {
  return (s || '').toLowerCase().replace(/\s+/g, ' ').trim().substring(0, 120)
}

// 安全 JSON 解析
function safeParse(s, defaultVal) {
  try { return JSON.parse(s) } catch(e) { return defaultVal }
}

// 截断字符串
function truncateStr(s, maxLen) {
  if (!s) return ''
  return s.length > maxLen ? s.substring(0, maxLen) + '…' : s
}
async function memoryMining() {
  const unminedTools = await dbGet('SELECT id, wallet, agent_id, tool_name, tool_params, result_data, result_status, error_message, duration_ms, created FROM tool_call_log WHERE mined_at IS NULL ORDER BY created ASC LIMIT 100')
  const unminedDialogs = await dbGet('SELECT context_id, wallet, user_message, ai_response, optimized_prompt FROM conversation_context WHERE analyzed = 0 ORDER BY created ASC LIMIT 100')

  const walletMaterials = new Map()

  for (const t of unminedTools) {
    if (!walletMaterials.has(t.wallet)) walletMaterials.set(t.wallet, { tools: [], dialogs: [] })
    walletMaterials.get(t.wallet).tools.push(t)
  }

  for (const d of unminedDialogs) {
    if (!walletMaterials.has(d.wallet)) walletMaterials.set(d.wallet, { tools: [], dialogs: [] })
    walletMaterials.get(d.wallet).dialogs.push(d)
  }

  if (walletMaterials.size === 0) return { mined: 0, wallets_affected: 0, knowledge_created: 0, knowledge_duped: 0 }

  let totalMined = 0
  let walletsAffected = 0
  let knowledgeCreated = 0
  let knowledgeDuped = 0

  for (const [wallet, materials] of walletMaterials) {
    if (materials.tools.length === 0 && materials.dialogs.length === 0) continue

    const agent = await dbFirst('SELECT agent_id, experience, resurrection_level FROM agents WHERE wallet = ?', [wallet])
    const chain = await dbFirst('SELECT chain_id, chain_length, chain_data FROM memory_chains WHERE wallet = ?', [wallet])
    let walletRewardMc = 0
    let walletRewardExp = 0
    let walletKnowledgeCount = 0
    let walletDupCount = 0

    for (const t of materials.tools) {
      if (!t.id) {
        console.warn('Skipping tool call with NULL id for wallet:', wallet)
        continue
      }
      const inputObj = safeParse(t.tool_params, {})
      const outputObj = safeParse(t.result_data, {})
      const inputSummary = truncateStr(JSON.stringify(inputObj), 300)
      const outputSummary = truncateStr(JSON.stringify(outputObj), 300)
      const errorSummary = t.error_message ? ` ERROR:${truncateStr(t.error_message, 100)}` : ''
      const content = `[${t.tool_name}] input:${inputSummary} → output:${outputSummary}${errorSummary}`
      const hash = normalizeHash(content)

      const existing = await dbFirst('SELECT knowledge_id, usage_count FROM memory_knowledge WHERE wallet = ? AND content_hash = ?', [wallet, hash])
      if (existing) {
        await dbRun('UPDATE memory_knowledge SET usage_count = usage_count + 1, last_accessed = ? WHERE knowledge_id = ?', [Date.now(), existing.knowledge_id])
        walletDupCount++
        console.log(`Dup knowledge for ${wallet}: ${hash.substring(0, 30)}`)
      } else {
        const qualityScore = computeQualityScore(content, 'tool_call')
        const reward = rewardForQuality(qualityScore)
        const knowledgeId = 'KNOW_' + randStr(8)
        console.log(`Creating knowledge for ${wallet}: score=${qualityScore}, reward=${reward.mc}MC, tier=${reward.tier}`)
        await dbRun('INSERT INTO memory_knowledge (knowledge_id, wallet, agent_id, source_type, source_id, content, content_hash, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, last_accessed, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          [knowledgeId, wallet, t.agent_id || '', 'tool_call', t.id, content, hash, 'fact', qualityScore, reward.mc, reward.exp, 1, Date.now(), Date.now(), 0])
        walletRewardMc += reward.mc
        walletRewardExp += reward.exp
        walletKnowledgeCount++
      }

      await dbRun('UPDATE tool_call_log SET mined_at = ? WHERE id = ?', [Date.now(), t.id])
      totalMined++
      console.log(`Mined tool ${t.id} for ${wallet}`)
    }

    for (const d of materials.dialogs) {
      const userSummary = truncateStr(d.user_message || d.optimized_prompt || '', 200)
      const aiSummary = truncateStr(d.ai_response || '', 300)
      const promptSummary = truncateStr(d.optimized_prompt || '', 150)
      
      // 根据 ai_response 是否为空，生成不同类型的知识
      let content, knowledgeType, sourceType
      if (aiSummary && aiSummary.length > 10) {
        // 完整对话知识（用于对话功能优化）
        content = `[dialog] user:${userSummary} → ai:${aiSummary}`
        knowledgeType = 'conversation'
        sourceType = 'dialog'
      } else {
        // 意图知识（用于上下文优化，即使 ai_response 为空也挖掘）
        content = `[intent] user:${userSummary} | context:${promptSummary}`
        knowledgeType = 'intent'
        sourceType = 'dialog_intent'
      }
      const hash = normalizeHash(content)

      const existing = await dbFirst('SELECT knowledge_id, usage_count FROM memory_knowledge WHERE wallet = ? AND content_hash = ?', [wallet, hash])
      if (existing) {
        await dbRun('UPDATE memory_knowledge SET usage_count = usage_count + 1, last_accessed = ? WHERE knowledge_id = ?', [Date.now(), existing.knowledge_id])
        walletDupCount++
      } else {
        const qualityScore = computeQualityScore(content, sourceType)
        const reward = rewardForQuality(qualityScore)
        const knowledgeId = 'KNOW_' + randStr(8)
        await dbRun('INSERT INTO memory_knowledge (knowledge_id, wallet, agent_id, source_type, source_id, content, content_hash, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, last_accessed, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          [knowledgeId, wallet, '', sourceType, d.context_id, content, hash, knowledgeType, qualityScore, reward.mc, reward.exp, 1, Date.now(), Date.now(), 0])
        walletRewardMc += reward.mc
        walletRewardExp += reward.exp
        walletKnowledgeCount++
      }

      await dbRun('UPDATE conversation_context SET analyzed = 1 WHERE context_id = ?', [d.context_id])
      totalMined++
    }

    try {
      await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [walletRewardMc, wallet])

      if (agent) {
        const newExp = (agent.experience || 0) + walletRewardExp
        const newLevel = Math.floor(newExp / 50)
        await dbRun('UPDATE agents SET experience = ?, resurrection_level = ?, balance = balance + ? WHERE wallet = ?', [newExp, newLevel, walletRewardMc, wallet])
      }

      if (chain && agent) {
        const chainEvent = { type: 'knowledge_extracted', wallet, items_consumed: materials.tools.length + materials.dialogs.length, knowledge_new: walletKnowledgeCount, knowledge_duped: walletDupCount, reward_mc: Math.round(walletRewardMc * 1000) / 1000, reward_exp: walletRewardExp, chain_length: chain.chain_length, timestamp: Date.now() }
        const existingData = JSON.parse(chain.chain_data || '[]')
        existingData.push(chainEvent)
        const newChainData = JSON.stringify(existingData)
        await dbRun('UPDATE memory_chains SET chain_data = ?, chain_length = chain_length + 1, updated = ? WHERE chain_id = ?', [newChainData, Date.now(), chain.chain_id])
      }

      if (chain) {
        const node = await dbFirst('SELECT mining_power FROM wallet_nodes WHERE wallet = ?', [wallet])
        if (node) {
          const chainBonus = chain.chain_length * 0.05
          const levelBonus = agent ? Math.floor((agent.experience || 0) / 50) * 0.25 : 0
          const basePower = 1.0
          const newPower = basePower + chainBonus + levelBonus
          await dbRun('UPDATE wallet_nodes SET mining_power = ? WHERE wallet = ?', [Math.round(newPower * 100) / 100, wallet])
        }
      }

      walletsAffected++
      knowledgeCreated += walletKnowledgeCount
      knowledgeDuped += walletDupCount
      console.log(`Mining complete for ${wallet}: ${walletKnowledgeCount} new, ${walletDupCount} duped, ${walletRewardMc}MC`)
    } catch(e) {
      console.error(`Mining failed for ${wallet}:`, e.message)
    }
  }

  return { mined: totalMined, wallets_affected: walletsAffected, knowledge_created: knowledgeCreated, knowledge_duped: knowledgeDuped, network_time: Date.now() }
}

// ============================================================
// 🤖 LLM 算力接口（v7.0：钱包分身算力接口）
// 用大模型 API Key 作为钱包分身的算力，后台完成记忆挖矿/任务挖矿/记忆优化
// ============================================================

// 加密密钥：优先用环境变量 LLM_ENC_KEY，否则由管理员密钥派生
async function llmEncKey() {
  if (ENV?.LLM_ENC_KEY) return ENV.LLM_ENC_KEY
  return await hmacSign(getAdminApiKey() || 'memorypalace', 'llm-enc-key-v1')
}

// 轻量 XOR 混淆存储（Worker 无持久主密钥，用于防止明文泄露）
async function encryptLlmKey(plain) {
  const key = await llmEncKey()
  const enc = new TextEncoder()
  const data = enc.encode(plain || '')
  const k = enc.encode(key)
  const out = new Uint8Array(data.length)
  for (let i = 0; i < data.length; i++) out[i] = data[i] ^ k[i % k.length]
  let bin = ''
  for (let i = 0; i < out.length; i++) bin += String.fromCharCode(out[i])
  return 'v1:' + btoa(bin)
}
async function decryptLlmKey(enc) {
  if (!enc) return ''
  const key = await llmEncKey()
  let payload = enc
  if (payload.startsWith('v1:')) payload = payload.slice(3)
  const bin = atob(payload)
  const k = new TextEncoder().encode(key)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i) ^ k[i % k.length]
  return new TextDecoder().decode(out)
}

// 读取某钱包的 LLM 配置（未指定钱包时取空钱包全局配置）
async function getLlmConfig(wallet) {
  const w = wallet || ''
  const rows = await dbGet('SELECT * FROM llm_config WHERE wallet = ? ORDER BY id DESC LIMIT 1', [w])
  return rows[0] || null
}

// 获取某钱包的配置（脱敏返回，绝不返回明文 Key）
async function llmConfigGet(url) {
  const wallet = url?.searchParams?.get('wallet') || ''
  const cfg = await getLlmConfig(wallet)
  if (!cfg) return json({ configured: false, wallet: wallet ? maskWallet(wallet) : '', network_time: Date.now() })
  return json({
    configured: true,
    wallet: wallet ? maskWallet(wallet) : '',
    provider: cfg.provider,
    base_url: cfg.base_url,
    model: cfg.model,
    api_key_masked: cfg.api_key_enc ? 'sk-***' + (cfg.api_key_enc.length > 8 ? cfg.api_key_enc.slice(-4) : '') : '',
    daily_limit: cfg.daily_limit,
    daily_used: cfg.daily_used,
    reset_day: cfg.reset_day,
    temperature: cfg.temperature,
    max_tokens: cfg.max_tokens,
    enabled: !!cfg.enabled,
    updated_at: cfg.updated_at,
    network_time: Date.now()
  })
}

// 保存某钱包的配置（wallet 为空时保存为全局默认，兼容旧逻辑）
async function llmConfigSet(body) {
  const { wallet, provider, base_url, model, api_key, daily_limit, temperature, max_tokens, enabled } = body
  const w = wallet || ''
  const existing = await getLlmConfig(w)
  const now = Date.now()
  if (existing) {
    const encKey = api_key ? await encryptLlmKey(api_key) : existing.api_key_enc
    await dbRun('UPDATE llm_config SET provider = ?, base_url = ?, model = ?, api_key_enc = ?, daily_limit = ?, temperature = ?, max_tokens = ?, enabled = ?, updated_at = ? WHERE id = ?',
      [provider || existing.provider, base_url || existing.base_url, model || existing.model, encKey, daily_limit ?? existing.daily_limit, temperature ?? existing.temperature, max_tokens ?? existing.max_tokens, enabled === undefined ? existing.enabled : (enabled ? 1 : 0), now, existing.id])
  } else {
    if (!api_key) throw new Error('首次配置需提供 api_key')
    await dbRun('INSERT INTO llm_config (wallet, provider, base_url, model, api_key_enc, daily_limit, temperature, max_tokens, enabled, updated_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [w, provider || 'openai', base_url || 'https://api.openai.com/v1', model || 'gpt-4o-mini', await encryptLlmKey(api_key), daily_limit || 200, temperature ?? 0.7, max_tokens || 1200, enabled === undefined ? 1 : (enabled ? 1 : 0), now, now])
  }
  return json({ saved: true, configured: true, wallet: w ? maskWallet(w) : '', api_key_masked: 'sk-***', daily_limit: daily_limit ?? existing?.daily_limit ?? 200, network_time: Date.now() })
}

// OpenAI 兼容 LLM 调用（带每日额度控制，按钱包使用各自配置）
async function llmChat(messages, opts = {}) {
  const cfg = await getLlmConfig(opts.wallet)
  if (!cfg || !cfg.api_key_enc) throw new Error('该钱包尚未配置 LLM，请先在钱包页填写 API Key')
  if (!cfg.enabled) throw new Error('LLM 算力已被停用')
  const today = new Date().toISOString().slice(0, 10)
  if (cfg.reset_day !== today) {
    await dbRun('UPDATE llm_config SET daily_used = 0, reset_day = ? WHERE id = ?', [today, cfg.id])
    cfg.daily_used = 0
    cfg.reset_day = today
  }
  if ((cfg.daily_used || 0) >= cfg.daily_limit) throw new Error(`今日 LLM 调用额度已用完（${cfg.daily_used}/${cfg.daily_limit}）`)
  const apiKey = await decryptLlmKey(cfg.api_key_enc)
  const base = (cfg.base_url || 'https://api.openai.com/v1').replace(/\/+$/, '')
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), opts.json ? 45000 : 30000)
  let res
  try {
    res = await fetch(base + '/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
      body: JSON.stringify({
        model: cfg.model || 'gpt-4o-mini',
        messages,
        temperature: opts.temperature ?? cfg.temperature ?? 0.7,
        max_tokens: opts.max_tokens || cfg.max_tokens || 1200,
        response_format: opts.json ? { type: 'json_object' } : undefined
      }),
      signal: controller.signal
    })
  } finally { clearTimeout(timer) }
  if (!res.ok) {
    const errText = (await res.text().catch(() => '')).slice(0, 200)
    throw new Error(`LLM 调用失败 ${res.status}: ${errText}`)
  }
  const data = await res.json()
  const usage = data.usage || { prompt_tokens: 0, completion_tokens: 0 }
  cfg.daily_used += 1
  await dbRun('UPDATE llm_config SET daily_used = ?, reset_day = ? WHERE id = ?', [cfg.daily_used, today, cfg.id])
  await dbRun('INSERT INTO llm_usage (task_type, model, wallet, target_id, input_tokens, output_tokens, cost_usd, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
    [opts.task_type || 'general', cfg.model, opts.wallet || '', opts.target_id || '', usage.prompt_tokens || 0, usage.completion_tokens || 0, 0, 'success', Date.now()])
  return { content: data.choices?.[0]?.message?.content || '', usage }
}

// 从 LLM 输出中提取 JSON
function extractJson(s) {
  if (!s) return null
  const m = s.match(/\{[\s\S]*\}/)
  return m ? m[0] : null
}

// ① 任务挖矿：自动接取（claim）→ 完成 → 提交（结算），奖励归分身钱包
async function llmTaskMining(maxCalls, wallet) {
  const limit = Math.max(1, Math.min(2, maxCalls))
  let completed = 0
  let calls = 0
  // 1. 先完成本钱包分身已认领未提交的任务（排除 PoW 算力任务，PoW 归算力节点）
  const claimed = await dbGet(`SELECT * FROM tasks WHERE status = 'claimed' AND completed_by IS NULL AND claimed_by IN (SELECT agent_id FROM agents WHERE wallet = ?) AND task_id NOT LIKE 'TASK_POW_%' AND room != 'mining' ORDER BY created ASC LIMIT ${limit}`, [wallet || ''])
  for (const task of claimed) {
    if (calls >= maxCalls) break
    const agent = await dbFirst('SELECT * FROM agents WHERE agent_id = ?', [task.claimed_by])
    if (!agent) continue
    try {
      const r = await llmChat([
        { role: 'system', content: '你是记忆宫殿中的分身助手。请根据任务要求完成工作，输出简洁可验证的结果（中文，200字内，包含关键步骤与产出物）。' },
        { role: 'user', content: `任务：${task.title}\n要求：${task.description || '无'}\n所在房间：${task.room || 'general'}\n请输出完成结果。` }
      ], { task_type: 'task_complete', wallet: agent.wallet, target_id: task.task_id, max_tokens: 500 })
      calls++
      const compRes = await taskComplete({ task_id: task.task_id, agent_id: task.claimed_by, result: truncateStr(r.content, 800) })
      const comp = await compRes.json().catch(() => null)
      const rewardMc = comp?.final_reward || 0
      const rewardExp = rewardMc * 10
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
        ['task_complete', agent.wallet, task.task_id, truncateStr(task.title, 100), truncateStr(r.content, 200), rewardMc, rewardExp, 'success', Date.now()])
      completed++
    } catch(e) {
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        ['task_complete', agent?.wallet || '', task.task_id, truncateStr(task.title, 100), '', 'failed', truncateStr(e.message, 200), Date.now()])
      console.error(`llm task complete failed ${task.task_id}:`, e.message)
    }
  }
  // 2. 自动接取未认领的真实任务（排除 PoW 算力任务，PoW 归算力节点；只接发布者支付/治理类任务）
  if (calls < maxCalls) {
    const best = await dbFirst('SELECT * FROM agents WHERE wallet = ? ORDER BY resurrection_level DESC, experience DESC LIMIT 1', [wallet || ''])
    if (best) {
      const level = best.resurrection_level || 0
      const open = await dbGet(`SELECT * FROM tasks WHERE status = 'active' AND room != 'mining' AND task_id NOT LIKE 'TASK_POW_%' AND required_level <= ${level} ORDER BY reward DESC, created ASC LIMIT ${Math.max(1, Math.min(2, maxCalls - calls))}`)
      for (const task of open) {
        if (calls >= maxCalls) break
        try {
          // 接取任务
          const claimRes = await taskClaim({ task_id: task.task_id, agent_id: best.agent_id, wallet: best.wallet })
          const claimBody = await claimRes.json().catch(() => null)
          if (!claimBody || claimBody.claimed !== true) continue
          // 完成并提交
          const r = await llmChat([
            { role: 'system', content: '你是记忆宫殿中的分身助手。请根据任务要求完成工作，输出简洁可验证的结果（中文，200字内，包含关键步骤与产出物）。' },
            { role: 'user', content: `任务：${task.title}\n要求：${task.description || '无'}\n所在房间：${task.room || 'general'}\n请输出完成结果。` }
          ], { task_type: 'task_complete', wallet: best.wallet, target_id: task.task_id, max_tokens: 500 })
          calls++
          const compRes2 = await taskComplete({ task_id: task.task_id, agent_id: best.agent_id, wallet: best.wallet, result: truncateStr(r.content, 800) })
          const comp2 = await compRes2.json().catch(() => null)
          const rewardMc2 = comp2?.final_reward || 0
          const rewardExp2 = rewardMc2 * 10
          await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
            ['task_auto_complete', best.wallet, task.task_id, truncateStr(task.title, 100), truncateStr(r.content, 200), rewardMc2, rewardExp2, 'success', Date.now()])
          completed++
        } catch(e) {
          await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
            ['task_auto_complete', best.wallet, task.task_id, truncateStr(task.title, 100), '', 'failed', truncateStr(e.message, 200), Date.now()])
          console.error(`llm task auto failed ${task.task_id}:`, e.message)
        }
      }
    }
  }
  return { completed, calls }
}

// ② 原料生成：用 LLM 把本钱包的工具调用提炼为高密度知识（减轻上传密度）
async function llmMaterialGenerate(maxCalls, wallet) {
  const limit = Math.max(1, Math.min(3, maxCalls))
  const unmined = await dbGet(`SELECT id, wallet, agent_id, tool_name, tool_params, result_data, result_status, error_message FROM tool_call_log WHERE mined_at IS NULL AND wallet = ? ORDER BY created ASC LIMIT ${limit}`, [wallet || ''])
  let generated = 0
  let calls = 0
  for (const t of unmined) {
    if (calls >= maxCalls) break
    try {
      const r = await llmChat([
        { role: 'system', content: '你是记忆宫殿的知识提炼引擎。请把一次工具调用提炼为结构化知识，只输出 JSON：{"title":"简短标题","content":"精炼知识内容（中文60-150字，保留关键参数与结果）","type":"fact|insight|skill"}，不要输出其他内容。' },
        { role: 'user', content: `工具：${t.tool_name}\n输入：${truncateStr(t.tool_params || '', 500) || '无'}\n输出：${truncateStr(t.result_data || '', 800) || '无'}${t.error_message ? '\n错误：' + truncateStr(t.error_message, 100) : ''}` }
      ], { task_type: 'material_generate', wallet: t.wallet, target_id: t.id, json: true, max_tokens: 400 })
      calls++
      const parsed = safeParse(extractJson(r.content), null)
      const content = parsed?.content || truncateStr(r.content, 300)
      const ktype = ['fact', 'insight', 'skill'].includes(parsed?.type) ? parsed.type : 'fact'
      const full = `[${t.tool_name}] ${content}`
      const hash = normalizeHash(full)
      const existing = await dbFirst('SELECT knowledge_id FROM memory_knowledge WHERE wallet = ? AND content_hash = ?', [t.wallet, hash])
      let rewardMc = 0
      let rewardExp = 0
      if (!existing) {
        const qs = Math.min(100, computeQualityScore(full, 'tool_call') + 10)
        const reward = rewardForQuality(qs)
        rewardMc = reward.mc
        rewardExp = reward.exp
        await dbRun('INSERT INTO memory_knowledge (knowledge_id, wallet, agent_id, source_type, source_id, content, content_hash, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, last_accessed, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          ['KNOW_' + randStr(8), t.wallet, t.agent_id || '', 'llm_mined', t.id, full, hash, ktype, qs, rewardMc, rewardExp, 1, Date.now(), Date.now(), 1])
        await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [rewardMc, t.wallet])
        if (t.agent_id) {
          const ag = await dbFirst('SELECT experience FROM agents WHERE agent_id = ?', [t.agent_id])
          if (ag) await dbRun('UPDATE agents SET experience = experience + ? WHERE agent_id = ?', [rewardExp, t.agent_id])
        }
      }
      await dbRun('UPDATE tool_call_log SET mined_at = ? WHERE id = ?', [Date.now(), t.id])
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
        ['material_generate', t.wallet, t.id, truncateStr(t.tool_name, 50), truncateStr(content, 150), rewardMc, rewardExp, 'success', Date.now()])
      generated++
    } catch(e) {
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        ['material_generate', t.wallet, t.id, truncateStr(t.tool_name, 50), '', 'failed', truncateStr(e.message, 200), Date.now()])
      console.error(`llm material failed ${t.id}:`, e.message)
    }
  }
  return { generated, calls }
}

// ③ 记忆优化：用 LLM 重写本钱包的提示词，提升记忆质量
async function llmMemoryOptimize(maxCalls, wallet) {
  const limit = Math.max(1, Math.min(3, maxCalls))
  const rows = await dbGet(`SELECT context_id, wallet, user_message, ai_response, optimization_score FROM conversation_context WHERE wallet = ? AND (analyzed = 0 OR optimization_score < 50) ORDER BY created ASC LIMIT ${limit}`, [wallet || ''])
  let optimized = 0
  let calls = 0
  for (const d of rows) {
    if (calls >= maxCalls) break
    try {
      const r = await llmChat([
        { role: 'system', content: '你是记忆宫殿的对话优化引擎。请把用户输入改写为更清晰、上下文更完整的优化提示词（中文，保留原意，补充隐含上下文与意图，50-150字），只输出优化后的提示词文本。' },
        { role: 'user', content: `用户输入：${truncateStr(d.user_message || '', 500)}\nAI 回复：${truncateStr(d.ai_response || '（无）', 500)}\n优化后提示词：` }
      ], { task_type: 'memory_optimize', wallet: d.wallet, target_id: d.context_id, max_tokens: 400 })
      calls++
      const optimizedPrompt = truncateStr((r.content || '').trim(), 1000)
      const optScore = Math.min(95, 50 + Math.min(45, Math.floor(optimizedPrompt.length / 10)))
      await dbRun('UPDATE conversation_context SET optimized_prompt = ?, optimization_score = ?, analyzed = 1 WHERE context_id = ?', [optimizedPrompt, optScore, d.context_id])
      const hash = normalizeHash(optimizedPrompt)
      const existing = await dbFirst('SELECT knowledge_id FROM memory_knowledge WHERE wallet = ? AND content_hash = ?', [d.wallet, hash])
      if (!existing) {
        const qs = Math.min(100, computeQualityScore(optimizedPrompt, 'dialog') + 15)
        const reward = rewardForQuality(qs)
        await dbRun('INSERT INTO memory_knowledge (knowledge_id, wallet, agent_id, source_type, source_id, content, content_hash, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, last_accessed, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          ['KNOW_' + randStr(8), d.wallet, '', 'llm_optimized', d.context_id, optimizedPrompt, hash, 'intent', qs, reward.mc, reward.exp, 1, Date.now(), Date.now(), 1])
        await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [reward.mc, d.wallet])
      }
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
        ['memory_optimize', d.wallet, d.context_id, truncateStr(d.user_message || '', 100), truncateStr(optimizedPrompt, 150), 0, 0, 'success', Date.now()])
      optimized++
    } catch(e) {
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        ['memory_optimize', d.wallet, d.context_id, truncateStr(d.user_message || '', 100), '', 'failed', truncateStr(e.message, 200), Date.now()])
      console.error(`llm memory optimize failed ${d.context_id}:`, e.message)
    }
  }
  return { optimized, calls }
}

// ④ 记忆治理：分身整理节点记忆，产出大模型可调阅的高密度知识（记忆链/工作链沉淀）
// 治理对象：钱包内未被提炼的对话上下文 + 工具调用，由 LLM 归纳出可复用的洞察，
// 结果写入 memory_knowledge（source_type=govern）并入记忆链，实现「让记忆成为模型上下文」。
// 文本重合度：中文 bigram Jaccard（0~1），记忆点/区块按重合度聚类划分
function textOverlap(a, b) {
  const toBigram = s => {
    const t = (s || '').replace(/\s+/g, '').toLowerCase()
    const set = new Set()
    for (let i = 0; i < t.length - 1; i++) set.add(t.slice(i, i + 2))
    return set
  }
  const A = toBigram(a), B = toBigram(b)
  if (A.size === 0 || B.size === 0) return 0
  let inter = 0
  for (const g of A) if (B.has(g)) inter++
  return inter / (A.size + B.size - inter)
}

// 贪心聚类：按指定字段的记忆重合度，找出最大的一组（组内平均重合度最高）
function findOverlapGroup(items, minSize, maxSize, threshold, field = 'content') {
  let bestGroup = null
  let bestScore = 0
  for (let i = 0; i < items.length; i++) {
    const group = [items[i]]
    for (let j = 0; j < items.length; j++) {
      if (i === j || group.length >= maxSize) continue
      let s = 0
      for (const m of group) s += textOverlap(String(items[j][field] || ''), String(m[field] || ''))
      if (s / group.length >= threshold) group.push(items[j])
    }
    if (group.length >= minSize) {
      let score = 0, n = 0
      for (let a = 0; a < group.length; a++) for (let b = a + 1; b < group.length; b++) { score += textOverlap(String(group[a][field] || ''), String(group[b][field] || '')); n++ }
      const avg = n ? score / n : 0
      if (avg > bestScore) { bestScore = avg; bestGroup = group }
    }
  }
  return bestGroup ? { group: bestGroup, score: bestScore } : null
}

// 记忆区块归纳：把重合度最高的一组治理知识（记忆点）LLM 归纳为一个记忆区块
async function induceOneBlock(wallet) {
  const rows = await dbGet(`SELECT knowledge_id, content FROM memory_knowledge WHERE wallet = ? AND mined = 1 AND (blocked IS NULL OR blocked = 0) ORDER BY created ASC LIMIT 40`, [wallet || ''])
  if (!rows || rows.length < 3) return { made: false, calls: 0 }
  const best = findOverlapGroup(rows, 3, 10, 0.28)
  if (!best || best.group.length < 3) return { made: false, calls: 0 } // 尚无足够重合的记忆点，等积累
  try {
    const list = best.group.map((r, i) => `${i + 1}. ${truncateStr(r.content, 120)}`).join('\n')
    const r = await llmChat([
      { role: 'system', content: '你是记忆宫殿的区块归纳引擎。把一组重合的记忆点（治理知识）归纳为一个记忆区块，提炼共同主题、关键结论与可复用方法。只输出 JSON：{"title":"区块主题(20字内)","content":"区块内容摘要(中文80-200字)","tags":["标签"]}，不要输出其他内容。' },
      { role: 'user', content: `重合记忆点（共${best.group.length}条）：\n${list}\n请归纳为记忆区块。` }
    ], { task_type: 'memory_block', wallet: wallet, json: true, max_tokens: 400 })
    const parsed = safeParse(extractJson(r.content), null)
    const title = parsed?.title || '记忆区块'
    const content = parsed?.content || truncateStr(r.content, 300)
    const knowledgeIds = best.group.map(r => r.knowledge_id)
    const blockId = 'BLK_' + randStr(8)
    const full = `[区块] ${title} —— ${content}`
    const qs = Math.min(100, computeQualityScore(full, 'dialog') + 20)
    const reward = rewardForQuality(qs)
    await dbRun('INSERT INTO memory_blocks (block_id, wallet, agent_id, title, content, knowledge_ids, knowledge_count, quality_score, level, checksum, created, cored) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [blockId, wallet, '', title, content, JSON.stringify(knowledgeIds), knowledgeIds.length, qs, 1, await hmacSign(full, wallet), Date.now(), 0])
    await dbRun(`UPDATE memory_knowledge SET blocked = 1 WHERE knowledge_id IN (${knowledgeIds.map(() => '?').join(',')})`, knowledgeIds)
    await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [reward.mc, wallet])
    // 沉淀入记忆链（工作链）
    try {
      const ag = await dbFirst('SELECT agent_id FROM agents WHERE wallet = ? ORDER BY resurrection_level DESC LIMIT 1', [wallet])
      if (ag) await memoryChainAppend(ag.agent_id, wallet, { type: 'memory_block', title, content, knowledge_count: knowledgeIds.length })
    } catch(e) {}
    await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
      ['memory_block', wallet, blockId, truncateStr(title, 100), truncateStr(content, 150), reward.mc, reward.exp, 'success', Date.now()])
    return { made: true, calls: 1 }
  } catch(e) {
    await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      ['memory_block', wallet, '', '记忆区块归纳', '', 'failed', truncateStr(e.message, 200), Date.now()])
    return { made: false, calls: 1, failed: true }
  }
}

// 记忆核提炼：把重合度最高的一组记忆区块跨区块 LLM 提炼为记忆核（最精炼、可长期调阅的核心知识）
async function induceOneCore(wallet) {
  const rows = await dbGet(`SELECT block_id, title, content FROM memory_blocks WHERE wallet = ? AND (cored IS NULL OR cored = 0) ORDER BY created ASC LIMIT 30`, [wallet || ''])
  if (!rows || rows.length < 2) return { made: false, calls: 0 }
  const best = findOverlapGroup(rows, 2, 6, 0.22, 'content')
  if (!best || best.group.length < 2) return { made: false, calls: 0 } // 尚无足够重合的区块，等积累
  try {
    const list = best.group.map((r, i) => `${i + 1}. [${r.title}] ${truncateStr(r.content, 150)}`).join('\n')
    const r = await llmChat([
      { role: 'system', content: '你是记忆宫殿的核心提炼引擎。把一组重合的记忆区块跨区块提炼为一条记忆核（core）——全局最核心、最高价值的精炼知识，供大模型作为长期上下文直接调阅。只输出 JSON：{"title":"核心主题(20字内)","content":"记忆核(中文60-150字)，凝聚这些区块共同的高价值结论/行为模式/关键技能","core_type":"behavior|skill|preference|relation|fact"}，不要输出其他内容。' },
      { role: 'user', content: `重合区块（共${best.group.length}个）：\n${list}\n请提炼为记忆核。` }
    ], { task_type: 'memory_core', wallet: wallet, json: true, max_tokens: 300 })
    const parsed = safeParse(extractJson(r.content), null)
    const title = parsed?.title || '记忆核'
    const content = parsed?.content || truncateStr(r.content, 250)
    const coreType = ['behavior', 'skill', 'preference', 'relation', 'fact'].includes(parsed?.core_type) ? parsed.core_type : 'behavior'
    const blockIds = best.group.map(r => r.block_id)
    const coreId = 'CORE_' + randStr(8)
    const full = `[核] ${title} —— ${content}`
    const qs = Math.min(100, computeQualityScore(full, 'dialog') + 30)
    const reward = rewardForQuality(qs)
    await dbRun('INSERT INTO memory_cores (core_id, wallet, agent_id, title, content, block_ids, block_count, core_type, quality_score, checksum, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [coreId, wallet, '', title, content, JSON.stringify(blockIds), blockIds.length, coreType, qs, await hmacSign(full, wallet), Date.now()])
    await dbRun(`UPDATE memory_blocks SET cored = 1 WHERE block_id IN (${blockIds.map(() => '?').join(',')})`, blockIds)
    await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [reward.mc, wallet])
    // 沉淀入记忆链（工作链）
    try {
      const ag = await dbFirst('SELECT agent_id FROM agents WHERE wallet = ? ORDER BY resurrection_level DESC LIMIT 1', [wallet])
      if (ag) await memoryChainAppend(ag.agent_id, wallet, { type: 'memory_core', title, content, block_count: blockIds.length, core_type: coreType })
    } catch(e) {}
    await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
      ['memory_core', wallet, coreId, truncateStr(title, 100), truncateStr(content, 150), reward.mc, reward.exp, 'success', Date.now()])
    return { made: true, calls: 1 }
  } catch(e) {
    await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      ['memory_core', wallet, '', '记忆核提炼', '', 'failed', truncateStr(e.message, 200), Date.now()])
    return { made: false, calls: 1, failed: true }
  }
}

// 记忆升级：一轮内递归「知识 → 区块 → 记忆核」，按需逐级升级（新块落库后立刻可升核）
async function memoryUpgrade(maxCalls, wallet) {
  let blocks = 0, cores = 0, calls = 0, blockFailed = false, coreFailed = false
  let progressed = true
  while (calls < maxCalls && progressed && !(blockFailed && coreFailed)) {
    progressed = false
    // ① 升块：知识 → 区块
    if (!blockFailed && calls < maxCalls) {
      const r = await induceOneBlock(wallet)
      calls += r.calls
      if (r.made) { blocks++; progressed = true }
      if (r.failed) blockFailed = true
    }
    // ② 升核：区块 → 记忆核（新块已落库，直接可被提炼）
    if (!coreFailed && calls < maxCalls) {
      const r = await induceOneCore(wallet)
      calls += r.calls
      if (r.made) { cores++; progressed = true }
      if (r.failed) coreFailed = true
    }
  }
  return { blocks, cores, calls }
}

async function llmMemoryGovern(maxCalls, wallet) {
  const limit = Math.max(1, Math.min(2, maxCalls))
  let governed = 0
  let calls = 0
  // 汇集本钱包尚未治理的对话上下文（含记忆上下文与工具使用）
  const rows = await dbGet(`SELECT context_id, user_message, ai_response, tools_used, memory_context, optimized_prompt FROM conversation_context WHERE wallet = ? AND (optimization_score IS NULL OR optimization_score < 50) ORDER BY created ASC LIMIT ${limit}`, [wallet || ''])
  for (const d of rows) {
    if (calls >= maxCalls) break
    try {
      const tools = safeParse(d.tools_used || '[]', [])
      const memRefs = safeParse(d.memory_context || '[]', [])
      const r = await llmChat([
        { role: 'system', content: '你是记忆宫殿的治理引擎。请把一段对话 + 调用工具提炼为高密度、可被大模型直接调阅的工作链知识。只输出 JSON：{"title":"简短标题","content":"精炼洞察（中文80-200字），包含对话意图、所用工具、可复用方法或结论","tags":["标签1","标签2"]}，不要输出其他内容。' },
        { role: 'user', content: `对话：${truncateStr(d.user_message || '', 400)}\nAI回复：${truncateStr(d.ai_response || '（无）', 400)}\n使用工具：${truncateStr(JSON.stringify(tools), 200) || '无'}\n关联记忆：${truncateStr(JSON.stringify(memRefs), 200) || '无'}\n请提炼治理性知识。` }
      ], { task_type: 'memory_govern', wallet: d.wallet, target_id: d.context_id, json: true, max_tokens: 400 })
      calls++
      const parsed = safeParse(extractJson(r.content), null)
      const content = parsed?.content || truncateStr(r.content, 300)
      const title = parsed?.title || '记忆治理'
      const tags = Array.isArray(parsed?.tags) ? parsed.tags.slice(0, 5) : []
      const full = `[治理] ${title} —— ${content}`
      const hash = normalizeHash(full)
      const existing = await dbFirst('SELECT knowledge_id FROM memory_knowledge WHERE wallet = ? AND content_hash = ?', [d.wallet, hash])
      let rewardMc = 0
      let rewardExp = 0
      if (!existing) {
        const qs = Math.min(100, computeQualityScore(full, 'dialog') + 10)
        const reward = rewardForQuality(qs)
        rewardMc = reward.mc
        rewardExp = reward.exp
        await dbRun('INSERT INTO memory_knowledge (knowledge_id, wallet, agent_id, source_type, source_id, content, content_hash, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, last_accessed, created, mined) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
          ['KNOW_' + randStr(8), d.wallet, '', 'govern', d.context_id, full, hash, tags.includes('skill') ? 'skill' : 'insight', qs, rewardMc, rewardExp, 1, Date.now(), Date.now(), 1])
        await dbRun('UPDATE wallets SET balance = balance + ? WHERE wallet = ?', [rewardMc, d.wallet])
        // 沉淀入记忆链（工作链），供大模型作为上下文调阅
        try {
          const ag = await dbFirst('SELECT agent_id FROM agents WHERE wallet = ? ORDER BY resurrection_level DESC LIMIT 1', [d.wallet])
          if (ag) await memoryChainAppend(ag.agent_id, d.wallet, { type: 'govern_knowledge', title, content, tags })
        } catch(e) {}
      }
      await dbRun('UPDATE conversation_context SET optimization_score = MAX(optimization_score, 50), analyzed = 1 WHERE context_id = ?', [d.context_id]).catch(async () => {
        await dbRun('UPDATE conversation_context SET optimization_score = 50, analyzed = 1 WHERE context_id = ?', [d.context_id])
      })
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)',
        ['memory_govern', d.wallet, d.context_id, truncateStr(title, 100), truncateStr(content, 150), rewardMc, rewardExp, 'success', Date.now()])
      governed++
    } catch(e) {
      await dbRun('INSERT INTO llm_mining_log (task_type, wallet, target_id, input_summary, output_summary, status, error_message, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        ['memory_govern', d.wallet, d.context_id, '记忆治理', '', 'failed', truncateStr(e.message, 200), Date.now()])
      console.error(`llm govern failed ${d.context_id}:`, e.message)
    }
  }
  return { governed, calls }
}

// LLM 自动挖矿总调度（scheduled 自动 + /api/llm/run 手动触发，按钱包）
async function llmAutoMining(mode = 'all', manual = false, wallet = '') {
  const cfg = await getLlmConfig(wallet)
  if (!cfg || !cfg.api_key_enc) return { configured: false, wallet: wallet ? maskWallet(wallet) : '', reason: 'llm not configured' }
  if (!cfg.enabled) return { enabled: false, wallet: wallet ? maskWallet(wallet) : '', reason: 'llm disabled' }
  const today = new Date().toISOString().slice(0, 10)
  if (cfg.reset_day !== today) {
    await dbRun('UPDATE llm_config SET daily_used = 0, reset_day = ? WHERE id = ?', [today, cfg.id])
    cfg.daily_used = 0
    cfg.reset_day = today
  }
  if ((cfg.daily_used || 0) >= cfg.daily_limit) return { limited: true, wallet: wallet ? maskWallet(wallet) : '', used: cfg.daily_used, limit: cfg.daily_limit }

  const result = { configured: true, wallet: wallet ? maskWallet(wallet) : '', memories_governed: 0, memory_blocks_induced: 0, memory_cores_induced: 0, materials_generated: 0, memories_optimized: 0, tasks_completed: 0, llm_calls: 0, network_time: Date.now() }
  const budget = manual ? 6 : 3

  // ① 记忆治理优先：整理节点记忆 + 优化工具调用 + 图谱内容 → 沉淀记忆链，形成模型可调阅的上下文/工作链数据
  if ((mode === 'all' || mode === 'govern') && result.llm_calls < budget) {
    try { const r = await llmMemoryGovern(budget - result.llm_calls, wallet); result.memories_governed += r.governed; result.llm_calls += r.calls } catch(e) { console.error('llm memory govern:', e.message) }
  }
  // ①b 记忆升级：一轮内递归「知识 → 区块 → 记忆核」，按需逐级升级（升出的新块同轮即升核）
  if ((mode === 'all' || mode === 'govern') && result.llm_calls < budget) {
    try { const r = await memoryUpgrade(budget - result.llm_calls, wallet); result.memory_blocks_induced += r.blocks; result.memory_cores_induced += r.cores; result.llm_calls += r.calls } catch(e) { console.error('memory upgrade:', e.message) }
  }
  // ② 原料生成：工具调用提炼为高密度知识（减轻上传密度）
  if ((mode === 'all' || mode === 'material') && result.llm_calls < budget) {
    try { const r = await llmMaterialGenerate(budget - result.llm_calls, wallet); result.materials_generated += r.generated; result.llm_calls += r.calls } catch(e) { console.error('llm material generate:', e.message) }
  }
  // ③ 记忆优化：重写提示词，提升记忆质量
  if ((mode === 'all' || mode === 'memory') && result.llm_calls < budget) {
    try { const r = await llmMemoryOptimize(budget - result.llm_calls, wallet); result.memories_optimized += r.optimized; result.llm_calls += r.calls } catch(e) { console.error('llm memory optimize:', e.message) }
  }
  // ④ 外部真任务最后：只接发布者支付/治理类（已排除 PoW 算力任务），不抢占治理预算
  if ((mode === 'all' || mode === 'task') && result.llm_calls < budget) {
    try { const r = await llmTaskMining(budget - result.llm_calls, wallet); result.tasks_completed += r.completed; result.llm_calls += r.calls } catch(e) { console.error('llm task mining:', e.message) }
  }
  return result
}

// LLM 用量统计（按钱包，可公开）
async function llmStatsGet(url) {
  const wallet = url?.searchParams?.get('wallet') || ''
  const wc = wallet ? ' AND wallet = ?' : ''
  const wp = wallet ? [wallet] : []
  const cfg = await getLlmConfig(wallet)
  const days = url?.searchParams?.get('days') ? parseInt(url.searchParams.get('days')) : 7
  const since = Date.now() - days * 86400000
  const [usage, todayUsage, logs, rawCounts] = await Promise.all([
    dbGet('SELECT task_type, COUNT(*) as calls, SUM(input_tokens) as in_tokens, SUM(output_tokens) as out_tokens FROM llm_usage WHERE created > ?' + wc + ' GROUP BY task_type', [since, ...wp]),
    dbGet('SELECT COUNT(*) as calls, SUM(input_tokens) as in_tokens, SUM(output_tokens) as out_tokens FROM llm_usage WHERE created > ?' + wc, [Date.now() - 86400000, ...wp]),
    dbGet('SELECT task_type, wallet, target_id, input_summary, output_summary, reward_mc, reward_exp, status, error_message, created FROM llm_mining_log WHERE 1=1' + wc + ' ORDER BY created DESC LIMIT 20', wp),
    (async () => {
      const tryCnt = async (sql, params) => { try { const r = await dbFirst(sql, params); return r?.cnt || 0 } catch(e) { return -1 } }
      const wc2 = wallet ? ' AND wallet = ?' : ''
      return {
        ungoverned: await tryCnt('SELECT COUNT(*) cnt FROM conversation_context WHERE (optimization_score IS NULL OR optimization_score < 50)' + wc2, wallet ? [wallet] : []),
        unmined: await tryCnt('SELECT COUNT(*) cnt FROM tool_call_log WHERE mined_at IS NULL' + wc2, wallet ? [wallet] : []),
        unblocked: await tryCnt('SELECT COUNT(*) cnt FROM memory_knowledge WHERE mined = 1 AND (blocked IS NULL OR blocked = 0)' + wc2, wallet ? [wallet] : []),
        uncored: await tryCnt('SELECT COUNT(*) cnt FROM memory_blocks WHERE (cored IS NULL OR cored = 0)' + wc2, wallet ? [wallet] : []),
        online_nodes: await tryCnt(`SELECT COUNT(*) cnt FROM wallet_nodes WHERE status = 'online'`, [])
      }
    })()
  ])
  return json({
    configured: !!cfg,
    wallet: wallet ? maskWallet(wallet) : '',
    model: cfg?.model || null,
    daily_limit: cfg?.daily_limit || 0,
    daily_used: cfg?.daily_used || 0,
    enabled: !!(cfg?.enabled),
    period_days: days,
    raw_counts: rawCounts || { ungoverned: 0, unmined: 0, unblocked: 0, uncored: 0, online_nodes: 0 },
    usage_by_type: usage,
    today: todayUsage[0] || { calls: 0, in_tokens: 0, out_tokens: 0 },
    recent_logs: logs,
    network_time: Date.now()
  })
}

// 管理员只读审计：按钱包/分身聚合链路上全部真实数据（供验证任务/知识点真实性）
async function adminAudit(url) {
  const wallet = url?.searchParams?.get('wallet') || ''
  const agent = url?.searchParams?.get('agent_id') || ''
  if (!wallet && !agent) return json({ error: 'wallet or agent_id required' }, 400)
  const out = { network_time: Date.now() }
  const q = async (sql, params) => (await dbGet(sql, params)) || []
  if (wallet) {
    out.wallet = await dbFirst('SELECT wallet, balance, agent_id, registered_at FROM wallets WHERE wallet = ?', [wallet])
    out.agents = await q('SELECT agent_id, balance, experience, resurrection_level, status, created FROM agents WHERE wallet = ? ORDER BY created ASC', [wallet])
    out.knowledge = await q('SELECT knowledge_id, source_type, source_id, content, knowledge_type, quality_score, reward_mc, reward_exp, usage_count, created, mined FROM memory_knowledge WHERE wallet = ? ORDER BY created DESC LIMIT 100', [wallet])
    out.llm_logs = await q('SELECT task_type, target_id, input_summary, output_summary, reward_mc, reward_exp, status, error_message, created FROM llm_mining_log WHERE wallet = ? ORDER BY created DESC LIMIT 100', [wallet])
    out.llm_usage = await q('SELECT task_type, model, target_id, input_tokens, output_tokens, cost_usd, status, error_message, created FROM llm_usage WHERE wallet = ? ORDER BY created DESC LIMIT 100', [wallet])
    out.tool_calls = await q('SELECT id, tool_name, result_status, mined_at, created FROM tool_call_log WHERE wallet = ? ORDER BY created DESC LIMIT 50', [wallet])
    out.contexts = await q('SELECT context_id, user_message, optimization_score, analyzed, created FROM conversation_context WHERE wallet = ? ORDER BY created DESC LIMIT 50', [wallet])
    out.blocks = await q('SELECT block_id, title, content, knowledge_count, quality_score, cored, created FROM memory_blocks WHERE wallet = ? ORDER BY created DESC LIMIT 50', [wallet])
    out.cores = await q('SELECT core_id, title, content, block_count, core_type, quality_score, created FROM memory_cores WHERE wallet = ? ORDER BY created DESC LIMIT 50', [wallet])
    out.dialog_cache = await q('SELECT id, agent_id, score, usage_count, created FROM dialog_cache WHERE wallet = ? ORDER BY created DESC LIMIT 50', [wallet])
  }
  if (agent) {
    out.agent = await dbFirst('SELECT * FROM agents WHERE agent_id = ?', [agent])
    out.tasks = await q('SELECT task_id, title, reward, room, status, claimed_by, completed_by, created, deadline, result FROM tasks WHERE claimed_by = ? OR completed_by = ? ORDER BY created DESC LIMIT 100', [agent, agent])
  }
  return json(out)
}

async function miningSync(body) {
  const { wallet, mining_power, blocks_found, hash_rate } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  const syncId = 'MS_' + randStr(8)
  await dbRun('INSERT INTO mining_sync_log (sync_id, wallet, mining_power, blocks_found, hash_rate, created) VALUES (?, ?, ?, ?, ?, ?)',
    [syncId, wallet, mining_power || 1.0, blocks_found || 0, hash_rate || 0, Date.now()])
  // 更新节点算力
  const node = await dbFirst('SELECT * FROM wallet_nodes WHERE wallet = ?', [wallet])
  if (node) {
    await dbRun('UPDATE wallet_nodes SET mining_power = ?, last_heartbeat = ?, status = ? WHERE wallet = ?', [mining_power || node.mining_power, Date.now(), 'online', wallet])
  } else {
    const nodeId = 'NODE_' + randStr(6)
    await dbRun('INSERT INTO wallet_nodes (wallet, node_id, status, last_heartbeat, connected_rooms, mining_power, latency_ms, updated) VALUES (?, ?, ?, ?, ?, ?, ?, ?)', [wallet, nodeId, 'online', Date.now(), '[]', mining_power || 1.0, 0, Date.now()])
  }
  return json({ synced: true, sync_id: syncId, mining_power: mining_power || 1.0, network_time: Date.now() })
}

// 全局挖矿统计（无需认证）
async function miningBackground() {
  const [nodes, syncLog, totalPower] = await Promise.all([
    dbGet('SELECT wallet, node_id, status, mining_power, last_heartbeat FROM wallet_nodes ORDER BY mining_power DESC'),
    dbGet('SELECT wallet, mining_power, blocks_found, hash_rate, created FROM mining_sync_log ORDER BY created DESC LIMIT 20'),
    dbFirst('SELECT SUM(mining_power) as total FROM wallet_nodes WHERE status = ?', ['online'])
  ])
  return json({
    global_stats: {
      total_nodes: nodes.length,
      online_nodes: nodes.filter(n => n.status === 'online').length,
      total_mining_power: totalPower?.total || 0,
      total_blocks_found: syncLog.reduce((s, l) => s + (l.blocks_found || 0), 0),
      avg_hash_rate: syncLog.length > 0 ? syncLog.reduce((s, l) => s + (l.hash_rate || 0), 0) / syncLog.length : 0
    },
    top_miners: nodes.slice(0, 10).map(n => ({
      wallet: maskWallet(n.wallet),
      node_id: n.node_id,
      status: n.status,
      mining_power: n.mining_power
    })),
    recent_syncs: syncLog.map(l => ({
      wallet: maskWallet(l.wallet),
      mining_power: l.mining_power,
      blocks_found: l.blocks_found,
      hash_rate: l.hash_rate,
      created: l.created
    })),
    network_time: Date.now()
  })
}

// 挖矿配置获取（从 strategies 表读取）
async function miningConfigGet() {
  const configs = await dbGet('SELECT key, value, updated_by, updated_at FROM strategies WHERE key IN (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
    ['mining_pool_base_reward','pow_task_reward','monitoring_reward_per_hour','auto_expand_threshold','expand_rate','decay_rate','decay_interval_ms','airdrop_rate','airdrop_interval_ms','optimize_task_reward','optimize_task_ttl'])
  const configMap = {}
  for (const c of configs) {
    configMap[c.key] = { value: c.value, updated_by: c.updated_by, updated_at: c.updated_at }
  }
  return json({
    config: configMap,
    mining_keys: {
      mining_pool_base_reward: configMap.mining_pool_base_reward?.value || '0.005',
      pow_task_reward: configMap.pow_task_reward?.value || '1.0',
      monitoring_reward_per_hour: configMap.monitoring_reward_per_hour?.value || '0.01',
      auto_expand_threshold: configMap.auto_expand_threshold?.value || '5.0',
      expand_rate: configMap.expand_rate?.value || '0.1',
      decay_rate: configMap.decay_rate?.value || '0.95',
      decay_interval_ms: configMap.decay_interval_ms?.value || '600000',
      airdrop_rate: configMap.airdrop_rate?.value || '0.01',
      airdrop_interval_ms: configMap.airdrop_interval_ms?.value || '600000'
    },
    network_time: Date.now()
  })
}

// 挖矿配置更新（写入 strategies 表）
async function miningConfigSet(body) {
  const { key, value, wallet } = body
  if (!key || !value) return json({ error: 'key and value required' }, 400)
  const validKeys = [
    'mining_pool_base_reward', 'pow_task_reward', 'monitoring_reward_per_hour',
    'auto_expand_threshold', 'expand_rate', 'decay_rate', 'decay_interval_ms',
    'airdrop_rate', 'airdrop_interval_ms', 'optimize_task_reward', 'optimize_task_ttl'
  ]
  if (!validKeys.includes(key)) return json({ error: 'invalid config key', valid_keys: validKeys }, 400)
  await dbRun('INSERT OR REPLACE INTO strategies (key, value, updated_by, updated_at) VALUES (?, ?, ?, ?)',
    [key, String(value), wallet || 'system', Date.now()])
  return { updated: true, key, value, network_time: Date.now() }
}

// 挖矿状态获取
async function miningStatusGet() {
  const [nodes, syncLog, totalPower, knowledgeCount, pendingMined] = await Promise.all([
    dbGet('SELECT wallet, node_id, status, mining_power, last_heartbeat FROM wallet_nodes ORDER BY mining_power DESC'),
    dbGet('SELECT wallet, mining_power, blocks_found, hash_rate, created FROM mining_sync_log ORDER BY created DESC LIMIT 10'),
    dbFirst('SELECT SUM(mining_power) as total FROM wallet_nodes WHERE status = ?', ['online']),
    dbFirst('SELECT COUNT(*) as count FROM memory_knowledge WHERE source_type IN (?, ?)', ['tool_call', 'dialog']),
    dbFirst('SELECT COUNT(*) as count FROM conversation_context WHERE analyzed = ?', [0])
  ])
  return json({
    status: 'active',
    nodes: {
      total: nodes.length,
      online: nodes.filter(n => n.status === 'online').length,
      total_power: totalPower?.total || 0
    },
    mining: {
      total_knowledge: knowledgeCount?.count || 0,
      pending_dialogs: pendingMined?.count || 0,
      recent_syncs: syncLog.length
    },
    top_miners: nodes.slice(0, 5).map(n => ({
      wallet: maskWallet(n.wallet),
      status: n.status,
      power: n.mining_power
    })),
    network_time: Date.now()
  })
}

// 挖矿启动（注册节点 + 更新状态）
async function miningStart(body) {
  const { wallet, agent_id } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  const w = await dbFirst('SELECT * FROM wallets WHERE wallet = ?', [wallet])
  if (!w) return json({ error: 'Wallet not found' }, 404)
  const node = await dbFirst('SELECT * FROM wallet_nodes WHERE wallet = ?', [wallet])
  if (node) {
    await dbRun('UPDATE wallet_nodes SET status = ?, last_heartbeat = ?, updated = ? WHERE wallet = ?', ['online', Date.now(), Date.now(), wallet])
    return json({ started: true, node_id: node.node_id, status: 'online', network_time: Date.now() })
  } else {
    const nodeId = 'NODE_' + randStr(6)
    await dbRun('INSERT INTO wallet_nodes (wallet, node_id, status, last_heartbeat, connected_rooms, mining_power, latency_ms, updated) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
      [wallet, nodeId, 'online', Date.now(), '[]', 1.0, 0, Date.now()])
    return json({ started: true, node_id: nodeId, status: 'online', new_node: true, network_time: Date.now() })
  }
}

