// 六十甲子
const SIXTY_CYCLE = [];
for (let i = 0; i < 60; i++) {
  const stem = HEAVENLY_STEMS[i % 10];
  const branch = EARTHLY_BRANCHES[i % 12];
  SIXTY_CYCLE.push({
    index: i + 1,
    stem: stem,
    branch: branch,
    combination: stem + branch,
    element: getStemElement(stem, branch),
    zodiac: getBranchZodiac(branch)
  });
}

function getStemElement(stem, branch) {
  const stemElements = { '甲': '木', '乙': '木', '丙': '火', '丁': '火', '戊': '土', '己': '土', '庚': '金', '辛': '金', '壬': '水', '癸': '水' };
  const branchElements = { '子': '水', '丑': '土', '寅': '木', '卯': '木', '辰': '土', '巳': '火', '午': '火', '未': '土', '申': '金', '酉': '金', '戌': '土', '亥': '水' };
  return { stem: stemElements[stem], branch: branchElements[branch] };
}

function getBranchZodiac(branch) {
  const zodiacs = { '子': '鼠', '丑': '牛', '寅': '虎', '卯': '兔', '辰': '龙', '巳': '蛇', '午': '马', '未': '羊', '申': '猴', '酉': '鸡', '戌': '狗', '亥': '猪' };
  return zodiacs[branch];
}

