// ============================================================
// Helper Functions
// ============================================================

function getLayerData(layer) {
  switch (layer) {
    case 'atomic': return ATOMIC_LAYER;
    case 'molecular': return MOLECULAR_LAYER;
    case 'logic': return LOGIC_LAYER;
    case 'worldview': return WORLDVIEW_LAYER;
    default: return null;
  }
}

function getCharacterLayer(char) {
  if (ATOMIC_LAYER[char]) return { layer: 'atomic', data: ATOMIC_LAYER[char] };
  if (MOLECULAR_LAYER[char]) return { layer: 'molecular', data: MOLECULAR_LAYER[char] };
  if (LOGIC_LAYER[char]) return { layer: 'logic', data: LOGIC_LAYER[char] };
  if (WORLDVIEW_LAYER[char]) return { layer: 'worldview', data: WORLDVIEW_LAYER[char] };
  return null;
}

function getMemoryChain(char) {
  const result = {
    character: char,
    layers: {},
    connections: {
      seasons: [],
      solarTerms: [],
      stems: null,
      branches: [],
      tones: [],
      idioms: []
    }
  };
  
  // Check each layer
  const layerData = getCharacterLayer(char);
  if (layerData) {
    result.layers[layerData.layer] = layerData.data;
  }
  
  // Check seasons
  for (const [key, season] of Object.entries(FOUR_SEASONS)) {
    if (season.months.includes(char) || key === char || season.element === char) {
      result.connections.seasons.push(season);
    }
  }
  
  // Check solar terms
  for (const [key, term] of Object.entries(SOLAR_TERMS)) {
    if (key.includes(char)) {
      result.connections.solarTerms.push({ name: key, ...term });
    }
  }
  
  // Check stems/branches
  if (HEAVENLY_STEMS.includes(char)) {
    result.connections.stems = { stem: char, element: WORLDVIEW_LAYER[char]?.element };
  }
  if (EARTHLY_BRANCHES.includes(char)) {
    result.connections.branches.push(WORLDVIEW_LAYER[char]);
  }
  
  // Check tones
  if (FIVE_TONES[char]) {
    result.connections.tones.push(FIVE_TONES[char]);
  }
  
  // Check idioms
  for (const [key, idiom] of Object.entries(CLASSICAL_IDIOMS)) {
    if (idiom.elements.includes(char)) {
      result.connections.idioms.push({ name: key, ...idiom });
    }
  }
  
  return result;
}

function getFiveElementsCycle() {
  return {
    generating: ['木→火→土→金→水→木'],
    overcoming: ['木→土→水→火→金→木'],
    description: '五行相生相克'
  };
}

function getSixtyCycleInfo(index) {
  if (index < 1 || index > 60) return null;
  return SIXTY_CYCLE[index - 1];
}


// ============================================================
// 🔥 汉字宇宙 v9.0 — 多层物理引擎 API
// ============================================================

// Get layer data (atomic/molecular/logic/worldview)
async function chineseLayer(url) {
  const layer = url.searchParams.get('layer') || '';
  const char = decodeURIComponent(url.searchParams.get('char') || '');
  
  if (char) {
    const data = getCharacterLayer(char);
    if (!data) return json({ error: `no layer data for '${char}'` }, 404);
    return json({ character: char, ...data });
  }
  
  const data = getLayerData(layer);
  if (!data) return json({ error: 'invalid layer. Use: atomic, molecular, logic, worldview' }, 400);
  return json({ layer, count: Object.keys(data).length, data });
}

// Get memory chain for a character
async function chineseMemoryChain(url) {
  const encoded = url.searchParams.get('char') || '';
  const char = decodeURIComponent(encoded);
  if (!char || [...char].length !== 1) return json({ error: 'single character required' }, 400);
  return json(getMemoryChain(char));
}

// Get four seasons data
async function chineseSeasons(url) {
  const char = decodeURIComponent(url.searchParams.get('char') || '');
  if (char) {
    if (FOUR_SEASONS[char]) return json(FOUR_SEASONS[char]);
    return json({ error: `no season data for '${char}'` }, 404);
  }
  return json(FOUR_SEASONS);
}

// Get 24 solar terms
async function chineseSolarTerms(url) {
  const term = decodeURIComponent(url.searchParams.get('term') || '');
  if (term) {
    if (SOLAR_TERMS[term]) return json(SOLAR_TERMS[term]);
    return json({ error: `no data for solar term '${term}'` }, 404);
  }
  return json(SOLAR_TERMS);
}

// Get heavenly stems and earthly branches
async function chineseStemsBranches(url) {
  const type = url.searchParams.get('type') || '';
  const char = decodeURIComponent(url.searchParams.get('char') || '');
  
  if (char) {
    if (HEAVENLY_STEMS.includes(char)) {
      return json({ type: 'stem', character: char, element: WORLDVIEW_LAYER[char]?.element, order: HEAVENLY_STEMS.indexOf(char) + 1 });
    }
    if (EARTHLY_BRANCHES.includes(char)) {
      return json({ type: 'branch', character: char, ...WORLDVIEW_LAYER[char] });
    }
    return json({ error: `'${char}' is not a stem or branch` }, 404);
  }
  
  if (type === 'stems') return json({ stems: HEAVENLY_STEMS });
  if (type === 'branches') return json({ branches: EARTHLY_BRANCHES });
  if (type === 'cycle') {
    const index = parseInt(url.searchParams.get('index') || '1');
    const info = getSixtyCycleInfo(index);
    if (!info) return json({ error: 'index must be 1-60' }, 400);
    return json(info);
  }
  
  return json({ stems: HEAVENLY_STEMS, branches: EARTHLY_BRANCHES, cycleLength: 60 });
}

// Get five tones
async function chineseTones(url) {
  const tone = decodeURIComponent(url.searchParams.get('tone') || '');
  if (tone) {
    if (FIVE_TONES[tone]) return json(FIVE_TONES[tone]);
    return json({ error: `no data for tone '${tone}'` }, 404);
  }
  return json(FIVE_TONES);
}

// Get classical idioms
async function chineseIdioms(url) {
  const idiom = decodeURIComponent(url.searchParams.get('idiom') || '');
  const category = url.searchParams.get('category') || '';
  const char = decodeURIComponent(url.searchParams.get('char') || '');
  
  if (idiom) {
    if (CLASSICAL_IDIOMS[idiom]) return json(CLASSICAL_IDIOMS[idiom]);
    return json({ error: `no data for idiom '${idiom}'` }, 404);
  }
  
  if (category) {
    const filtered = Object.entries(CLASSICAL_IDIOMS)
      .filter(([_, v]) => v.category === category)
      .map(([k, v]) => ({ name: k, ...v }));
    return json({ category, count: filtered.length, idioms: filtered });
  }
  
  if (char) {
    const filtered = Object.entries(CLASSICAL_IDIOMS)
      .filter(([_, v]) => v.elements.includes(char))
      .map(([k, v]) => ({ name: k, ...v }));
    return json({ character: char, count: filtered.length, idioms: filtered });
  }
  
  return json({ count: Object.keys(CLASSICAL_IDIOMS).length, idioms: CLASSICAL_IDIOMS });
}

// Get five elements cycle
async function chineseElementsCycle(url) {
  return json(getFiveElementsCycle());
}

// Get comprehensive stats
async function chineseStatsV9() {
  return json({
    version: '9.0.0',
    layers: {
      atomic: Object.keys(ATOMIC_LAYER).length,
      molecular: Object.keys(MOLECULAR_LAYER).length,
      logic: Object.keys(LOGIC_LAYER).length,
      worldview: Object.keys(WORLDVIEW_LAYER).length
    },
    extensions: {
      seasons: Object.keys(FOUR_SEASONS).length,
      solarTerms: Object.keys(SOLAR_TERMS).length,
      stems: HEAVENLY_STEMS.length,
      branches: EARTHLY_BRANCHES.length,
      tones: Object.keys(FIVE_TONES).length,
      idioms: Object.keys(CLASSICAL_IDIOMS).length
    },
    totalCharacters: Object.keys(CHAR_DECOMP).length,
    data_source: 'Unicode Unihan Database + Classical Chinese Philosophy',
    timestamp: Date.now()
  });
}
function getAbstractionRatio(chain) {
  if (!chain || chain.length < 2) return 0.0
  const first = chain[0].physicality
  const last = chain[chain.length - 1].physicality
  return first > 0 ? Math.round((first - last) / first * 100) / 100 : 0.0
}

function decomposeChar(char) {
  if (CHAR_DECOMP[char]) return CHAR_DECOMP[char]
  return { components: [char], structure: 'single', meaning: `汉字 ${char}（暂无详细拆解数据）`, evolution: '暂无演化数据' }
}

function getEvolutionChain(char) {
  return EVOLUTION_CHAINS[char] || null
}

function getPhysicsConcept(char) {
  return PHYSICS_CONCEPTS[char] || null
}

function compareChars(charA, charB) {
  const a = decomposeChar(charA)
  const b = decomposeChar(charB)
  const setA = [...new Set(a.components)]
  const setB = [...new Set(b.components)]
  const shared = setA.filter(c => setB.includes(c))
  const allComps = [...new Set([...setA, ...setB])]
  const dist = allComps.length === 0 ? 1.0 : Math.max(0, Math.round((1 - shared.length / allComps.length) * 100) / 100)
  const interactions = shared.map(c => ({ component: c, concept: getPhysicsConcept(c) })).filter(x => x.concept)
  return {
    char_a: charA, char_b: charB,
    shared_atoms: shared,
    semantic_distance: dist,
    physics_interactions: interactions
  }
}

function understandText(text) {
  const chars = [...text].filter(c => /[一-龥]/.test(c))
  const physicsInText = chars.map(getPhysicsConcept).filter(Boolean)
  const totalPhy = physicsInText.reduce((s, c) => s + c.physicality, 0)
  const depth = Math.min(1.0, physicsInText.length > 0 ? (totalPhy / physicsInText.length) * 0.8 : 0.2)
  return {
    text,
    chars_analyzed: chars.length,
    physics_concepts_found: physicsInText.length,
    understanding_depth: Math.round(depth * 100) / 100,
    physics_chars: physicsInText.map(c => c.name),
    timestamp: Date.now()
  }
}

function getFiveElements() {
  const elements = {}
  for (const [char, elem] of Object.entries(FIVE_ELEMENTS)) {
    if (!elements[elem]) elements[elem] = []
    elements[elem].push(char)
  }
  return elements
}

// API handlers
async function chineseUnderstand(body) {
  const text = body?.text || body?.q || ''
  if (!text) return json({ error: 'text required' }, 400)
  return json(understandText(text))
}

async function chineseDecompose(body) {
  const char = (body?.character || body?.char || body?.q || '').trim()
  if (!char || [...char].length !== 1) return json({ error: 'single character required' }, 400)
  return json({ character: char, ...decomposeChar(char) })
}

async function chineseEvolution(path) {
  const encoded = path.split('/').pop()
  const char = decodeURIComponent(encoded)
  if (!char || [...char].length !== 1) return json({ error: 'single character required' }, 400)
  const chain = getEvolutionChain(char)
  if (!chain) return json({ error: `no evolution chain for '${char}'` }, 404)
  return json({ character: char, concept: getPhysicsConcept(char), stages: chain, abstraction_ratio: getAbstractionRatio(chain) })
}

async function chinesePhysics(url) {
  const encoded = url.searchParams.get('name') || url.searchParams.get('char') || ''
  const name = decodeURIComponent(encoded)
  if (!name) return json({ error: 'name parameter required' }, 400)
  const concept = getPhysicsConcept(name)
  if (!concept) return json({ error: `no physics concept for '${name}'` }, 404)
  return json(concept)
}

async function chineseCompare(body) {
  const a = (body?.char_a || body?.a || '').trim()
  const b = (body?.char_b || body?.b || '').trim()
  if (!a || !b || [...a].length !== 1 || [...b].length !== 1) return json({ error: 'char_a and char_b (single chars) required' }, 400)
  return json(compareChars(a, b))
}

async function chineseFiveElements(url) {
  const encoded = url.searchParams.get('char') || url.searchParams.get('name') || ''
  const char = decodeURIComponent(encoded)
  if (char) {
    if ([...char].length !== 1) return json({ error: 'single character required' }, 400)
    const elem = FIVE_ELEMENTS[char]
    if (!elem) return json({ error: `no five-elements data for '${char}'` }, 404)
    return json({ character: char, element: elem })
  }
  return json(getFiveElements())
}

async function chineseStats() {
  return json({
    total_physics_concepts: Object.keys(PHYSICS_CONCEPTS).length,
    total_decomposition: Object.keys(CHAR_DECOMP).length,
    total_evolution_chains: Object.keys(EVOLUTION_CHAINS).length,
    five_elements: ['木','火','土','金','水'],
    categories: ['natural','human','body','cultural','abstract'],
    version: '8.0.0',
    data_source: 'Unicode Unihan Database',
    timestamp: Date.now()
  })
}

