// 💬 对话优化
// ============================================================
async function getWalletTier(wallet) {
  try {
    const agent = await dbFirst('SELECT experience, level FROM agents WHERE wallet = ?', [wallet])
    const lvl = agent?.level || 0
    if (lvl >= 50) return { level: 4, name: '记忆之神', color: '#ff00ff' }
    if (lvl >= 20) return { level: 3, name: '记忆贤者', color: '#ffaa00' }
    if (lvl >= 10) return { level: 2, name: '记忆大师', color: '#00cc6a' }
    if (lvl >= 5) return { level: 1, name: '记忆学徒', color: '#00aaff' }
    return { level: 0, name: '记忆新手', color: '#888888' }
  } catch (e) {
    return { level: 0, name: '记忆新手', color: '#888888' }
  }
}


async function dialogAnalyze(body) {
  const { wallet, agent_id, user_input, ai_response, feedback } = body
  if (!wallet || !user_input) return json({ error: 'wallet and user_input required' }, 400)
  const analysisId = 'ANL_' + randStr(8)
  // 计算质量分数
  let qualityScore = 0.5
  if (ai_response) qualityScore += Math.min(ai_response.length / 1000, 0.3)
  if (feedback === 'positive') qualityScore += 0.2
  else if (feedback === 'negative') qualityScore -= 0.1
  qualityScore = Math.max(0, Math.min(1, qualityScore))
  await dbRun('INSERT INTO dialog_analysis (analysis_id, wallet, agent_id, user_input, ai_response, feedback, quality_score, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
    [analysisId, wallet, agent_id || '', user_input, ai_response || '', feedback || 'neutral', qualityScore, Date.now()])
  try { await memoryChainAppend(agent_id || wallet, wallet, { type: 'dialog_analyze', quality_score: qualityScore, feedback }) } catch(e) {}
  return json({ analyzed: true, analysis_id: analysisId, quality_score: qualityScore, network_time: Date.now() })
}

