// 服务端图谱分析 - 关联发现
async function graphAnalyze(url) {
  const node_id = url.searchParams.get('node_id')
  if (!node_id) return json({ error: 'node_id required' }, 400)
  
  // 获取节点信息
  const node = await dbFirst('SELECT * FROM knowledge_graph_nodes WHERE node_id = ?', [node_id])
  if (!node) return json({ error: 'Node not found' }, 404)
  
  // 查找直接关联节点（服务端JOIN）
  const related = await dbGet(`
    SELECT e.weight, n.node_id, n.label, n.type, n.quality 
    FROM knowledge_graph_edges e 
    JOIN knowledge_graph_nodes n ON (e.source = ? AND e.target = n.node_id) OR (e.target = ? AND e.source = n.node_id)
    ORDER BY e.weight DESC LIMIT 20
  `, [node_id, node_id])
  
  // 计算聚类系数
  const neighborIds = related.map(r => r.node_id)
  let connections_between_neighbors = 0
  if (neighborIds.length > 1) {
    const placeholders = neighborIds.map(() => '?').join(',')
    const interConnections = await dbFirst(`
      SELECT COUNT(*) as count FROM knowledge_graph_edges 
      WHERE source IN (${placeholders}) AND target IN (${placeholders})
    `, [...neighborIds, ...neighborIds])
    connections_between_neighbors = interConnections?.count || 0
  }
  
  return json({
    node,
    related_nodes: related,
    cluster_stats: {
      neighbor_count: related.length,
      connections_between_neighbors,
      cluster_density: related.length > 1 ? connections_between_neighbors / (related.length * (related.length - 1) / 2) : 0
    },
    network_time: Date.now()
  })
}

// ============================================================
// 🧠 记忆系统 - 服务端处理，只返回分析结果
// ============================================================

// 服务端记忆蒸馏 - 聚合相似记忆，返回摘要
async function memoryDistill(body) {
  const { wallet, limit } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  
  const distillLimit = Math.min(parseInt(limit) || 20, 100)
  
  // 获取用户最近的记忆
  const entries = await dbGet('SELECT memory_id, content, memory_type, created FROM memory_entries WHERE wallet = ? ORDER BY created DESC LIMIT ?', [wallet, distillLimit])
  
  // 服务端分类统计
  const typeStats = {}
  const timeDistribution = {}
  const recentInsights = []
  
  for (const entry of entries) {
    // 按类型统计
    typeStats[entry.memory_type] = (typeStats[entry.memory_type] || 0) + 1
    
    // 按日期分布
    const date = new Date(entry.created).toISOString().split('T')[0]
    timeDistribution[date] = (timeDistribution[date] || 0) + 1
    
    // 提取关键信息（简单摘要）
    if (entry.content && entry.content.length > 10) {
      recentInsights.push({
        memory_id: entry.memory_id,
        type: entry.memory_type,
        preview: entry.content.substring(0, 100),
        created: entry.created
      })
    }
  }
  
  // 计算记忆质量趋势
  const scoredEntries = await dbGet('SELECT score, scored_at FROM memory_entries WHERE wallet = ? AND scored_at > 0 ORDER BY scored_at DESC LIMIT 10', [wallet])
  const avgScore = scoredEntries.length > 0 
    ? scoredEntries.reduce((sum, e) => sum + (e.score || 0), 0) / scoredEntries.length 
    : 0
  
  return json({
    distilled: true,
    wallet: maskWallet(wallet),
    summary: {
      total_memories: entries.length,
      type_distribution: typeStats,
      time_distribution: timeDistribution,
      average_score: Math.round(avgScore * 100) / 100,
      scored_count: scoredEntries.length
    },
    recent_insights: recentInsights.slice(0, 5),
    network_time: Date.now()
  })
}

// 服务端记忆链接分析
async function memoryLinkAnalysis(body) {
  const { wallet } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  
  // 获取用户的记忆链接统计
  const links = await dbGet('SELECT link_type, COUNT(*) as count, AVG(strength) as avg_strength FROM memory_links WHERE wallet = ? GROUP BY link_type', [wallet])
  
  // 查找高度关联的记忆簇
  const topLinks = await dbGet(`
    SELECT l.source_id, l.target_id, l.link_type, l.strength,
           m1.content as source_preview, m2.content as target_preview
    FROM memory_links l
    LEFT JOIN memory_entries m1 ON l.source_id = m1.memory_id
    LEFT JOIN memory_entries m2 ON l.target_id = m2.memory_id
    WHERE l.wallet = ?
    ORDER BY l.strength DESC
    LIMIT 10
  `, [wallet])
  
  // 计算链接覆盖率
  const counts = await dbFirst(`
    SELECT 
      (SELECT COUNT(*) FROM memory_entries WHERE wallet = ?) as total_memories,
      (SELECT COUNT(DISTINCT source_id) + COUNT(DISTINCT target_id) FROM memory_links WHERE wallet = ?) as linked_memories
  `, [wallet, wallet])
  
  return json({
    analysis: {
      total_links: links.reduce((sum, l) => sum + l.count, 0),
      type_breakdown: links,
      link_coverage: counts?.total_memories > 0 ? Math.round((counts?.linked_memories || 0) / counts.total_memories * 100) : 0,
      strongest_connections: topLinks.map(l => ({
        source: l.source_preview?.substring(0, 50),
        target: l.target_preview?.substring(0, 50),
        type: l.link_type,
        strength: l.strength
      }))
    },
    network_time: Date.now()
  })
}

// 服务端记忆分类统计
async function memoryClassify(body) {
  const { wallet } = body
  if (!wallet) return json({ error: 'wallet required' }, 400)
  
  // 按类型和质量统计
  const typeStats = await dbGet(`
    SELECT memory_type, 
           COUNT(*) as count, 
           AVG(score) as avg_score,
           MAX(created) as last_created
    FROM memory_entries 
    WHERE wallet = ? 
    GROUP BY memory_type
    ORDER BY count DESC
  `, [wallet])
  
  // 获取高质量记忆摘要
  const highQuality = await dbGet(`
    SELECT memory_id, content, score, created 
    FROM memory_entries 
    WHERE wallet = ? AND score >= 4
    ORDER BY score DESC, created DESC
    LIMIT 5
  `, [wallet])
  
  return json({
    classification: {
      type_stats: typeStats,
      high_quality_memories: highQuality.map(m => ({
        memory_id: m.memory_id,
        preview: m.content?.substring(0, 80),
        score: m.score,
        created: m.created
      }))
    },
    network_time: Date.now()
  })
}

