async function cloneStatusGet(url) {
  const agent_id = url.searchParams.get('agent_id')
  if (!agent_id) return json({ error: 'agent_id required' }, 400)
  const agent = await dbFirst('SELECT * FROM agents WHERE agent_id = ?', [agent_id])
  if (!agent) return json({ error: 'Agent not found' }, 404)
  const chain = await dbFirst('SELECT chain_id, chain_length, level, updated FROM memory_chains WHERE agent_id = ?', [agent_id])
  const identity = await dbFirst('SELECT clone_id, trust_score, status, last_verified FROM clone_identities WHERE agent_id = ?', [agent_id])
  return json({
    agent_id: agent.agent_id,
    wallet: maskWallet(agent.wallet),
    status: agent.status,
    main_status: agent.main_status,
    clone_status: agent.clone_status,
    memory_chain: chain,
    clone_identity: identity,
    network_time: Date.now()
  })
}

async function cloneSync(body) {
  const { agent_id, wallet, data } = body
  if (!agent_id || !wallet) return json({ error: 'agent_id and wallet required' }, 400)
  const agent = await dbFirst('SELECT * FROM agents WHERE agent_id = ? AND wallet = ?', [agent_id, wallet])
  if (!agent) return json({ error: 'Agent not found' }, 403)
  const cloneData = JSON.parse(agent.clone_data || '{}')
  Object.assign(cloneData, data || {})
  await dbRun('UPDATE agents SET clone_data = ?, last_sync = ? WHERE agent_id = ?', [JSON.stringify(cloneData), Date.now(), agent_id])
  try { await memoryChainAppend(agent_id, wallet, { type: 'clone_sync', data: JSON.stringify(data || {}).substring(0, 200) }) } catch(e) {}
  return json({ synced: true, agent_id, last_sync: Date.now(), network_time: Date.now() })
}

// ============================================================
// 💰 手动空投 / 衰减 / 节点惩罚
// ============================================================
async function poolAirdropManual(body) {
  const { wallet, amount, reason } = body
  if (!wallet || !amount) return json({ error: 'wallet and amount required' }, 400)
  const w = await dbFirst('SELECT * FROM wallets WHERE wallet = ?', [wallet])
  if (!w) return json({ error: 'Wallet not found' }, 404)
  const amt = parseFloat(amount)
  const newBalance = w.balance + amt
  await dbRun('UPDATE wallets SET balance = ? WHERE wallet = ?', [newBalance, wallet])
  await dbRun('INSERT INTO pool_transactions (id, wallet, type, amount, pool_balance_before, pool_balance_after, description, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
    ['TX_' + randStr(6), wallet, 'airdrop_manual', amt, w.balance, newBalance, reason || '手动空投', Date.now()])
  return json({ airdropped: true, wallet: maskWallet(wallet), amount: amt, new_balance: newBalance, reason: reason || '手动空投', network_time: Date.now() })
}

async function poolDecayManual(body) {
  const { wallet, percentage, reason } = body
  if (!wallet || !percentage) return json({ error: 'wallet and percentage required' }, 400)
  const w = await dbFirst('SELECT * FROM wallets WHERE wallet = ?', [wallet])
  if (!w) return json({ error: 'Wallet not found' }, 404)
  const pct = parseFloat(percentage)
  const decayAmount = w.balance * (pct / 100)
  const newBalance = w.balance - decayAmount
  await dbRun('UPDATE wallets SET balance = ? WHERE wallet = ?', [newBalance, wallet])
  await dbRun('INSERT INTO pool_transactions (id, wallet, type, amount, pool_balance_before, pool_balance_after, description, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
    ['TX_' + randStr(6), wallet, 'decay_manual', decayAmount, w.balance, newBalance, reason || '手动衰减', Date.now()])
  return json({ decayed: true, wallet: maskWallet(wallet), percentage: pct, decay_amount: decayAmount, new_balance: newBalance, reason: reason || '手动衰减', network_time: Date.now() })
}

async function nodePenalize(body) {
  const { node_id, amount } = body
  if (!node_id) return json({ error: 'node_id required' }, 400)
  const node = await dbFirst('SELECT * FROM wallet_nodes WHERE node_id = ?', [node_id])
  if (!node) return json({ error: 'Node not found' }, 404)
  const penalty = parseFloat(amount) || 0.1
  const newPower = Math.max(0, (node.mining_power || 1) - penalty)
  await dbRun('UPDATE wallet_nodes SET mining_power = ? WHERE node_id = ?', [newPower, node_id])
  await dbRun('INSERT INTO audit_log (id, wallet, action, target, result, reason, created) VALUES (?, ?, ?, ?, ?, ?, ?)',
    ['AUD_' + randStr(6), node.wallet, 'penalize', node_id, 'success', '算力惩罚 -' + penalty, Date.now()])
  return json({ penalized: true, node_id, new_power: newPower, network_time: Date.now() })
}
